def _named_job(name: str, fn, client):
    """A module's job wrapped for the scheduler, keeping its own name for /admin status."""
    async def run(now):
        await fn(client, now)
    run.__name__ = name
    return run


def env(name: str, default: str) -> str:
    """A setting from the environment; blank counts as not set."""
    return (os.getenv(name) or "").strip() or default


def env_int(name: str, default: int, low: int = 0, high: int = 10**6) -> int:
    try:
        value = int(env(name, str(default)))
        if low <= value <= high:
            return value
    except ValueError:
        pass
    log.warning("%s should be a whole number from %d to %d; using %d", name, low, high, default)
    return default


TOKEN = env("DISCORD_TOKEN", "")
_GUILD_RAW = env("GUILD_ID", "")
# Pasted IDs sometimes arrive with quotes, spaces or a stray backslash ("1067...\); keep just the digits.
GUILD_ID = "".join(ch for ch in _GUILD_RAW if ch.isdigit())
if _GUILD_RAW and (_GUILD_RAW != GUILD_ID or not 15 <= len(GUILD_ID) <= 21):
    log.warning("GUILD_ID on Railway should be just the server's number (no quotes); read it as %r", GUILD_ID or "nothing")
    if not 15 <= len(GUILD_ID) <= 21:
        GUILD_ID = ""
def parse_snowflakes(raw) -> list:
    """Discord user numbers from a paste: commas, spaces or one ID. Names are ignored; digits only."""
    out = []
    for part in re.split(r"[,\s;/]+", str(raw or "")):
        d = "".join(c for c in part if c.isdigit())
        if d:
            n = int(d)
            if n not in out:
                out.append(n)
    return out


# Crew ladder (Railway). Developers are the failsafe and cannot be removed from the bot.
# Owner has full permission. Extra admins/mods can also be added in Discord with /staff add.
DEVELOPER_IDS = parse_snowflakes(env("DEVELOPER_IDS", "") or env("DEVELOPER_ID", ""))
OWNER_IDS = parse_snowflakes(env("OWNER_IDS", "") or env("OWNER_ID", ""))
ADMIN_IDS = parse_snowflakes(env("ADMIN_IDS", ""))
MOD_IDS = parse_snowflakes(env("MOD_IDS", ""))
OWNER_ID = str(OWNER_IDS[0]) if OWNER_IDS else ""
ANTHROPIC_API_KEY = env("ANTHROPIC_API_KEY", "")
CLAUDE_MODEL = env("CLAUDE_MODEL", "claude-haiku-4-5-20251001")
ASK_MODEL = env("ASK_MODEL", "claude-sonnet-5-5")
ASK_DAILY_LIMIT = env_int("ASK_DAILY_LIMIT", 40)
ASK_COOLDOWN_SECONDS = env_int("ASK_COOLDOWN_SECONDS", 20)
MEMBERS_INTENT = env("MEMBERS_INTENT", "") in ("1", "true", "yes", "on")
DB_PATH = env("DB_PATH", "picks.db")

try:
    TZ = ZoneInfo(env("TIMEZONE", "America/Chicago"))
except Exception:
    log.warning("Unknown TIMEZONE; using America/Chicago")
    TZ = ZoneInfo("America/Chicago")
DAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]
_recap_day = env("RECAP_DAY", "sunday").lower()
RECAP_DAY = DAYS.index(_recap_day) if _recap_day in DAYS else DAYS.index("sunday")
RECAP_HOUR = env_int("RECAP_HOUR", 20, 0, 23)        # 8 PM
REMIND_HOUR = env_int("REMIND_HOUR", 12, 0, 23)      # noon
REMIND_AFTER_DAYS = env_int("REMIND_AFTER_DAYS", 3, 1, 365)
AUTOGRADE_AFTER_HOURS = env_int("AUTOGRADE_AFTER_HOURS", 48, 0, 24 * 60)   # 0 turns it off
