# ---- "log it" vs "what do you think?" -------------------------------------------------

SLIP_ASK = re.compile(r"\?|\b(what do (?:you|u|y'?all|yall) think|thoughts|rate (?:it|this|my)|rating|opinion|"
                      r"analy[sz]e|break (?:it |this )?down|breakdown|review|should i|would you|worth it|how(?:'s| is| does) "
                      r"(?:this|it|my)|any good|chances|honest)\b", re.I)


def slip_intent(text: str) -> str:
    """'ask' when the words with a screenshot are a question about it, otherwise 'log'."""
    t = re.sub(r"<@[!&]?\d+>", " ", text or "").strip()
    return "ask" if t and SLIP_ASK.search(t) else "log"


async def offer_extra_slips(message, slip) -> None:
    """A photo with two tickets stays two confirm cards. The picture is not copied onto either card."""
    if getattr(message, "guild", None) is None or not slip:
        return
    extras = list(slip.pop("_extra", None) or [])
    for extra in extras[:3]:
        if not isinstance(extra, dict) or not extra.get("legs"):
            continue
        extra.pop("_extra", None)
        note = await message.reply("Another slip was in that photo. Confirm this one on its own.",
                                   mention_author=False)
        mid = getattr(note, "id", None)
        if not mid:
            continue
        set_setting(message.guild.id, f"draft:{mid}", json.dumps({
            "slip": extra, "poster": message.author.id, "poster_name": message.author.display_name,
            "url": message.jump_url, "channel_id": message.channel.id, "used": None, "at": now_iso(),
            "typed": False, **filed_under(message)}))
        try:
            await note.edit(embed=slip_draft_embed(extra),
                            view=slip_draft_view(mid, review=ai_enabled(), edit=True))
        except Exception:
            log.warning("Couldn't attach the second slip card")


async def offer_extra_slips(message, slip) -> None:
    """A photo with two tickets gets a confirm card for each, instead of one merged slip."""
    extras = []
    if isinstance(slip, dict):
        extras = list(slip.pop("_extra", None) or [])
    for extra in extras[:3]:
        if not isinstance(extra, dict) or not extra.get("legs"):
            continue
        extra.pop("_extra", None)
        note = await message.reply("Another slip was in that photo. Confirm this one on its own.", mention_author=False)
        mid = getattr(note, "id", None)
        if not mid or message.guild is None:
            continue
        set_setting(message.guild.id, f"draft:{mid}", json.dumps({
            "slip": extra, "poster": message.author.id, "poster_name": message.author.display_name,
            "url": message.jump_url, "channel_id": message.channel.id, "used": None, "at": now_iso(),
            "typed": False, **filed_under(message)}))
        try:
            await note.edit(embed=slip_draft_embed(extra), view=slip_draft_view(mid, review=ai_enabled(), edit=True))
        except Exception:
            log.warning("Couldn't attach the second slip")


def save_slip_draft(guild_id: int, message, slip: dict, typed: bool = False, mention_from=None) -> None:
    payload = {
        "slip": slip, "poster": message.author.id, "poster_name": message.author.display_name,
        "url": message.jump_url, "channel_id": message.channel.id, "used": None, "at": now_iso(), "typed": typed}
    payload.update(filed_under(mention_from or message))
    set_setting(guild_id, f"draft:{message.id}", json.dumps(payload))


def get_slip_draft(guild_id: int, message_id: int) -> Optional[dict]:
    raw = get_setting(guild_id, f"draft:{message_id}")
    return json.loads(raw) if raw else None


class SlipDraftButton(discord.ui.DynamicItem[discord.ui.Button], template=r"sd:(?P<act>log|ask|edit):(?P<mid>\d+)"):
    def __init__(self, act: str, message_id: int):
        label, style = {"log": ("🧾 Log this slip", discord.ButtonStyle.secondary),
                        "ask": ("🔍 Break it down", discord.ButtonStyle.primary),
                        "edit": ("✏️ Edit", discord.ButtonStyle.secondary)}[act]
        super().__init__(discord.ui.Button(label=label, style=style, custom_id=f"sd:{act}:{message_id}"))
        self.act, self.message_id = act, message_id

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["act"], int(match["mid"]))

    async def callback(self, interaction: discord.Interaction):
        d = get_slip_draft(interaction.guild_id, self.message_id)
        if d is None:
            await interaction.response.send_message("I don't have that slip anymore. Post the screenshot again.",
                                                    ephemeral=True)
            return
        if self.act == "log":
            staff = can_file_for_others(interaction.user, interaction.guild_id)
            if interaction.user.id != d["poster"] and not staff:
                await interaction.response.send_message("Only whoever posted the slip can log it.", ephemeral=True)
                return
            if d.get("used"):
                await interaction.response.send_message(f"Already logged as pick `#{d['used']}`.", ephemeral=True)
                return
            if not d["slip"].get("cost"):
                await interaction.response.send_modal(DraftEditModal(self.message_id, d))
                return
            until = cooling_until(interaction.guild_id, interaction.user.id)
            if until:
                await interaction.response.send_message(cooloff_message(until), ephemeral=True)
                return
            await interaction.response.defer()
            d["used"] = -1
            set_setting(interaction.guild_id, f"draft:{self.message_id}", json.dumps(d))

            async def reply(**kw):
                return await interaction.followup.send(wait=True, **kw)
            bettor = None
            if staff and d.get("for_id"):
                bettor = _FiledWho(int(d["for_id"]), d.get("for_name") or "them")
            elif staff and interaction.user.id != d["poster"]:
                bettor = _FiledWho(int(d["poster"]), d.get("poster_name") or "them")
            try:
                pid = await interaction.client.log_parsed_slip(
                    interaction.guild_id, interaction.user, interaction.channel,
                    d["slip"], d["url"], reply, bettor=bettor, shot_message_id=self.message_id)
            except Exception:
                log.exception("Logging a draft failed")
                d["used"] = None
                set_setting(interaction.guild_id, f"draft:{self.message_id}", json.dumps(d))
                await interaction.followup.send("⚠️ Something went wrong logging that. Tap 🧾 again.", ephemeral=True)
                return
            d["used"] = pid
            set_setting(interaction.guild_id, f"draft:{self.message_id}", json.dumps(d))
            drop_ghost(interaction.guild_id, self.message_id)
            return
        if self.act == "edit":
            if interaction.user.id != d["poster"] or d.get("used"):
                await interaction.response.send_message("Only whoever posted the slip can edit it, before it's logged.",
                                                        ephemeral=True)
                return
            await interaction.response.send_modal(DraftEditModal(self.message_id, d))
            return
        gate = ask_gate(interaction.guild_id, interaction.user.id)
        if gate:
            await interaction.response.send_message(gate, ephemeral=True)
            return
        await interaction.response.defer(thinking=True)
        text, xray = await slip_review(interaction.client, interaction.guild_id, interaction.user, d["slip"],
                                       "Break this slip down for me.")
        chunks = split_message(text)
        for k, chunk in enumerate(chunks):
            extra = {}
            if k == 0 and xray is not None:
                extra["file"] = xray
            if k == len(chunks) - 1 and not d.get("used"):
                extra["view"] = slip_draft_view(self.message_id, review=False, edit=bool(d.get("typed")))
            await interaction.followup.send(chunk, allowed_mentions=discord.AllowedMentions.none(), **extra)


class SlipWhoSelect(discord.ui.DynamicItem[discord.ui.UserSelect], template=r"sd:who:(?P<mid>\d+)"):
    """Staff pick whose record a slip goes on. Anyone else is told to leave it."""

    def __init__(self, message_id: int):
        super().__init__(discord.ui.UserSelect(
            custom_id=f"sd:who:{message_id}",
            placeholder="Log it under someone else",
            min_values=1, max_values=1, row=1))
        self.message_id = message_id

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(int(match["mid"]))

    async def callback(self, interaction: discord.Interaction):
        if not can_file_for_others(interaction.user, interaction.guild_id):
            await interaction.response.send_message(
                "Only staff can log a slip under someone else.", ephemeral=True)
            return
        d = get_slip_draft(interaction.guild_id, self.message_id)
        if d is None:
            await interaction.response.send_message("I don't have that slip anymore. Post the screenshot again.",
                                                    ephemeral=True)
            return
        if d.get("used"):
            await interaction.response.send_message(f"Already logged as pick `#{d['used']}`.", ephemeral=True)
            return
        raw = (interaction.data or {}).get("values") or []
        uid = str(raw[0]) if raw else ""
        if not uid.isdigit():
            await interaction.response.send_message("Pick a person from the server.", ephemeral=True)
            return
        resolved = (interaction.data or {}).get("resolved") or {}
        member = (resolved.get("members") or {}).get(uid) or {}
        user = (resolved.get("users") or {}).get(uid) or {}
        name = member.get("nick") or user.get("global_name") or user.get("username") or "them"
        d["for_id"] = int(uid)
        d["for_name"] = clip(str(name), 60)
        set_setting(interaction.guild_id, f"draft:{self.message_id}", json.dumps(d))
        await interaction.response.send_message(
            f"This slip will be logged under **{d['for_name']}**. Tap 🧾 Log this slip.",
            ephemeral=True, allowed_mentions=discord.AllowedMentions.none())


def slip_draft_view(message_id: int, review: bool = True, log_it: bool = True, edit: bool = False) -> discord.ui.View:
    v = discord.ui.View(timeout=None)
    order = ("log", "edit", "ask") if edit else ("ask", "log")   # typed slips lead with Log; screenshots with the breakdown
    for act in order:
        if (act == "log" and log_it) or (act == "edit" and edit) or (act == "ask" and review):
            v.add_item(SlipDraftButton(act, message_id))
    if log_it:
        v.add_item(SlipWhoSelect(message_id))
    return v


def ask_gate(guild_id: int, user_id: int) -> Optional[str]:
    """Shares the @mention question limits. Returns why not, or None and counts the question."""
    wait = bot.ask_cooldowns.get(user_id, 0) + ASK_COOLDOWN_SECONDS - time.monotonic()
    if wait > 0:
        return f"Give me {int(wait) + 1}s before the next question."
    count_key = f"asks:{datetime.now(TZ).date().isoformat()}"
    used = int(get_setting(guild_id, count_key) or 0)
    if used >= ASK_DAILY_LIMIT:
        return f"That's the server's {ASK_DAILY_LIMIT} questions for today. Back tomorrow."
    bot.ask_cooldowns[user_id] = time.monotonic()
    set_setting(guild_id, count_key, str(used + 1))
    return None


REVIEW_RULES = """Someone posted a slip and asked what you think. It is NOT logged as a pick, and may not \
even be placed. Answer like a sharp friend:
- One line per leg: ✅ like it, ⚠️ coin flip or a real concern, ❌ don't like it, then the key reason (recent \
games against that number, minutes/role, matchup, injuries or rest). Base it on the game logs and injury report \
included below; never invent a stat.
- Then "Weakest leg:" and a one-line overall take. It's fine to say pass, or to swap the weakest leg.
- Use the group's own history (below, or the group_stats tool) when it says something.
- Never mention odds, prices, payouts math, hedging or line movement. Never call anything a lock, a sure \
thing, guaranteed or free money. Past games are a trend, not a promise. If a line looks misread, say so. Never \
never push them to bet more.
Keep it under 220 words."""


NB_BAD_STATUS = ("out", "doubtful", "suspension", "injured reserve", "ir")


def nb_leg(x: dict, inj: Optional[dict]) -> tuple[str, Optional[float]]:
    """(one line for this leg, a score for picking the weakest leg; None when there are no numbers)."""
    label = clip(x.get("text") or "?", 80)
    st = ((inj or {}).get("status") or "").strip()
    stl = st.lower()
    tag = f" · 🩹 listed **{clip(st, 24)}**" if st else ""
    h = xray_hits(x)
    if not h:
        return f"⚪ **{label}**: no game log to check ({x.get('why') or 'not found'}){tag}", None
    if line_suspect(x):
        vals = [v for _, _, v in x["values"]]
        return (f"❓ **{label}**: the line looks misread from the screenshot (he averages {sum(vals) / len(vals):.1f}). "
                f"Check the number on your slip.{tag}"), None
    good, n = h
    vals = [v for _, _, v in x["values"]]                       # oldest → newest
    beat = (lambda v: v > x["line"]) if x["side"] == "over" else (lambda v: v < x["line"])
    last5 = vals[-5:]
    good5 = sum(1 for v in last5 if beat(v))
    avg = sum(vals) / n
    diff = avg - x["line"]
    edge = diff if x["side"] == "over" else -diff
    rate = good / n
    if stl.startswith(NB_BAD_STATUS):
        icon = "❌"
    elif edge > 0 and ((rate >= 0.7 and good5 >= 3) or (rate >= 0.6 and good5 >= 4)):
        icon = "✅"
    elif rate <= 0.4 or (len(last5) >= 4 and good5 <= 1):
        icon = "❌"
    else:
        icon = "⚠️"
    if icon == "✅" and stl.startswith(("questionable", "day-to-day", "game-time")):
        icon = "⚠️"
    near = f"{abs(diff):.1f} {'above' if diff >= 0 else 'below'} the line" if abs(diff) >= 0.05 else "right on the line"
    last_vs = ""
    try:
        opp, at, _v = x["values"][-1]
        if opp:
            last_vs = f" · last {at or 'vs'} {opp}"
    except Exception:
        last_vs = ""
    text = (f"{icon} **{label}**: {good}/{n} {x['side']} · avg {avg:.1f} ({near}) · {good5} of the last "
            f"{len(last5)} · last game {vals[-1]:g}{last_vs}{tag}")
    score = rate + 0.04 * good5 + (-1.0 if stl.startswith(NB_BAD_STATUS) else 0.0) + \
        (-0.15 if stl.startswith("questionable") else 0.0)
    return text, score


def numbers_breakdown(data: list, injuries: Optional[dict] = None, notes: Optional[list] = None) -> str:
    """A leg-by-leg breakdown written straight from ESPN game logs and the injury report: free, unlimited, and every
    number in it is real. Used when no AI is set up or the AI is out of free uses."""
    injuries = injuries or {}
    rows, scored = [], []
    for x in data:
        line, score = nb_leg(x, injuries.get(x.get("name") or ""))
        rows.append(line)
        if score is not None:
            scored.append((score, x))
    if not rows:
        return "📊 I couldn't find game logs for this slip's legs, so there are no numbers to break down."
    out = ["📊 **The numbers** (each player's last games against this line)", *rows]
    if len(scored) >= 2:
        _, weak = min(scored, key=lambda t: t[0])
        h = xray_hits(weak)
        out.append(f"\n**Weakest leg:** {clip(weak['text'], 80)} ({h[0]}/{h[1]})")
    if scored:
        solid = sum(1 for sc, x in scored if (xray_hits(x)[0] / xray_hits(x)[1]) >= 0.6)
        out.append(f"{solid} of {len(scored)} legs with a game log cleared their number in at least 6 of 10 recent games.")
    missing = sum(1 for x in data if not xray_hits(x))
    if missing:
        out.append(f"{missing} leg{'s' if missing != 1 else ''} had no game log to check.")
    odd = sum(1 for x in data if xray_hits(x) and line_suspect(x))
    if odd:
        out.append(f"{odd} line{'s look' if odd != 1 else ' looks'} misread from the screenshot. Type the slip out "
                   "(like `Player Name over 0.5 Anytime TD`) and I'll check it again.")
    if notes:
        out.append("\n**Your group's history:**\n" + "\n".join(notes[:4]))
    out.append("-# Straight from ESPN game logs and injury reports. Past games aren't a promise.")
    return "\n".join(out)


async def xray_injuries(data: list) -> dict:
    """{player name: injury entry} for the X-ray's players who are on an injury report."""
    watch = {}
    for x in data or []:
        if x.get("name") and x.get("path") and x.get("path") in PROP_PATHS:
            watch[norm_name(x["name"])] = {"name": x["name"], "paths": [x["path"]], "slips": []}
    if not watch:
        return {}
    try:
        st = await asyncio.wait_for(news_status(watch), timeout=15)
    except Exception:
        return {}
    return {w["name"]: st[k] for k, w in watch.items() if st.get(k)}


def question_needs_search(question: str) -> bool:
    """Live facts need a lookup. A normal chat does not, so the reply can come back right away."""
    q = question or ""
    if re.search(
        r"\b(tonight|today|tomorrow|injury|injuries|injured|lineup|lineups|starting|score|scores|"
        r"news|latest|last night|right now|players?|teams?|games?|matchups?|match|standings?|"
        r"stats?|roster|weather|forecast|rain|wind|temperature|nba|nfl|mlb|nhl|wnba|soccer|ufc|"
        r"f1|golf|playoffs?|season|starter|benched|touchdowns?|rebounds|assists|homers?|goalie|"
        r"pitcher|played|playing|plays|schedule|kickoff|warmup)\b",
        q, re.I):
        return True
    # A real question that is not about sports still needs a check when the fact can change.
    return bool(re.search(
        r"\b(who|what|when|where|why|how|which|define|explain|capital|population|president|"
        r"price|cost|worth|history|versus|compare|difference|meaning)\b",
        q, re.I)) or ("?" in q and len(q.split()) >= 4)


def question_is_weather(question: str) -> bool:
    """A forecast question, including a plain 'what's the weather going to be'."""
    return bool(re.search(
        r"\b(weather|forecast|temperature|temp\b|rain|raining|windy|wind\b|how hot|how cold|degrees)\b",
        question or "", re.I))


def weather_place_phrase(question: str) -> Optional[str]:
    """City or team named after in/for/at/around/near. Empty when they didn't name a place."""
    m = re.search(r"\b(?:in|for|at|around|near)\s+([A-Za-z][A-Za-z .'-]{1,48})", question or "", re.I)
    if not m:
        return None
    raw = m.group(1)
    cut = re.search(r"\b(today|tonight|tomorrow|this|on|please|going|gonna|be|like|weather|forecast)\b",
                    raw, re.I)
    if cut:
        raw = raw[:cut.start()]
    name = re.sub(r"^(the|a|an)\s+", "", " ".join(raw.split()), flags=re.I).strip(" .,-'")
    if not name or name.split()[0].lower() in {"me", "us", "my", "the", "a", "an", "game", "match", "it", "there", "here"}:
        return None
    return name


_GENERIC_TAKE = re.compile(
    r"can'?t spot the legs|spill '?em|what are the names|break it down together|"
    r"couldn'?t (?:see|read|spot|make out) the (?:legs|picks|names)",
    re.I)


def take_is_generic(text: str) -> bool:
    """A shrug that names no line. A real take mentions an over or under, or a paid result."""
    if not text or len(text.strip()) < 20:
        return True
    if _GENERIC_TAKE.search(text) and not re.search(r"\b(over|under)\s+\d", text, re.I):
        return True
    return False


async def glance_talk(attachment, question: str, guild_id: int, name: str) -> str:
    """A spoken take when the slip parser came up empty. It has to name what is actually on the card."""
    if not ask_enabled():
        return ""
    asked = (question or "").strip() or "What do you think of this?"
    system = (
        "You are in a Discord group chat of friends who track sports picks. "
        f"Voice: {persona_prompt(guild_id)}. Address {name}. "
        "The picture is the whole question. Name the players and the lines you can read. "
        "If the card shows Win, Loss, or an amount paid, say that result and the dollars. "
        "When a row shows the actual stat, say which legs hit and which missed. "
        "Do not say you cannot see the legs when names are on the card. Do not ask them to retype the picks. "
        "Do not answer with a pep talk that could fit any screenshot. Two to six sentences. "
        "Do not invent a player, a stat, or a result that is not on the screen. "
        "Do not mention API keys, billing, credits, or model names."
    )
    user = f"{name} asked: {asked}"
    if GEMINI_API_KEY and attachment is not None:
        try:
            seen = await gemini_see(attachment, system + "\n\n" + user)
            if seen and len(seen) > 20 and not take_is_generic(seen):
                return seen
        except Exception:
            log.warning("Screenshot talk failed", exc_info=True)
    try:
        text, _ = await asyncio.wait_for(ask_any(system, user, search=False), timeout=8)
        text = (text or "").strip()
        return "" if take_is_generic(text) else text
    except Exception:
        log.warning("Chat take failed", exc_info=True)
        return ""


async def pull_choice_card(opt: dict) -> tuple[str, Optional[bytes]]:
    """One player's log, after someone picked them from a list of names. Returns (text, png bytes or None)."""
    stat = opt.get("stat") or ""
    if stat not in STATS or not opt.get("id") or not opt.get("path"):
        return "That name doesn't have a league on file.", None
    games = await trend_games(opt["path"], str(opt["id"]), need=12)
    games, src = await deepen_games(opt["path"], str(opt["id"]), opt.get("name") or "", stat, games, fast=False)
    values = trend_values(games, stat)[:10]
    line = opt.get("line")
    if line is None:
        line = default_line([v for _, v in values])
    try:
        line = float(line)
    except (TypeError, ValueError):
        line = default_line([v for _, v in values])
    side = opt.get("side") or "over"
    shown = [(g["opp"], g["at"], v) for g, v in values][::-1]
    row = {"text": opt.get("leg") or opt.get("name") or "", "values": shown, "line": line, "side": side,
           "name": opt.get("name"), "stat": STATS[stat][0],
           "why": "" if shown else "no recent games on that feed"}
    bits = [f"**{opt.get('name') or 'Player'}** · {STATS[stat][0]} · {side} {line:g}", src or "ESPN game log"]
    if not shown:
        bits.append("No recent games on that feed. Try another name.")
    png = None
    if shown:
        buf = await asyncio.to_thread(locked_render, render_xray, opt.get("name") or "Player", [row],
                                      "PLAYER LOG", opt.get("path"))
        png = buf.getvalue()
    return "\n".join(bits), png


class DataPickView(discord.ui.View):
    """Names that all fit one scanned leg. Pick one to pull that log. Back returns to the list."""

    def __init__(self, owner_id: int, options: list):
        super().__init__(timeout=900)
        self.owner_id = owner_id
        self.options = options[:8]
        self.frames = [("More than one player fits. Pick a name and I'll pull that log. Back returns to this list.", None)]
        self._paint()

    def _paint(self):
        self.clear_items()
        if len(self.frames) > 1:
            back = discord.ui.Button(label="Back", style=discord.ButtonStyle.secondary, row=0)
            back.callback = self._back
            self.add_item(back)
        for i, opt in enumerate(self.options):
            b = discord.ui.Button(label=(opt.get("label") or opt.get("name") or "Player")[:80],
                                  style=discord.ButtonStyle.secondary, row=1 + i // 4)
            b.callback = self._pick(i)
            self.add_item(b)

    async def _check(self, interaction) -> bool:
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("This list is for the person who posted the slip.", ephemeral=True)
            return False
        return True

    async def _show(self, interaction, content, png):
        self._paint()
        kwargs = {"content": content, "view": self}
        if png:
            kwargs["attachments"] = [discord.File(io.BytesIO(png), filename="player-log.png")]
        else:
            kwargs["attachments"] = []
        await interaction.response.edit_message(**kwargs)

    def _back(self):
        async def cb(interaction):
            if not await self._check(interaction):
                return
            if len(self.frames) > 1:
                self.frames.pop()
            content, png = self.frames[-1]
            await self._show(interaction, content, png)
        return cb

    def _pick(self, i):
        async def cb(interaction):
            if not await self._check(interaction):
                return
            try:
                content, png = await pull_choice_card(self.options[i])
            except Exception:
                log.warning("Player pull failed", exc_info=True)
                content, png = "I couldn't pull that log. Try another name.", None
            self.frames.append((content, png))
            await self._show(interaction, content, png)
        return cb


def data_pick_options(slip: dict) -> list:
    """Players we refused to guess, so the channel can offer them as buttons."""
    opts, seen = [], set()
    for x in slip.get("_xray") or []:
        if x.get("values"):
            continue
        for c in x.get("choices") or []:
            key = (c.get("path"), str(c.get("id")), c.get("stat"))
            if not c.get("id") or key in seen:
                continue
            seen.add(key)
            row = dict(c)
            row["leg"] = x.get("text") or row.get("leg") or ""
            row["line"] = x.get("line")
            row["side"] = x.get("side") or "over"
            opts.append(row)
    return opts[:8]


async def offer_data_picks(message, slip: dict) -> None:
    opts = data_pick_options(slip)
    if not opts:
        return
    try:
        await message.channel.send(
            "More than one player fits. Pick a name and I'll pull that log. Back returns to this list.",
            view=DataPickView(message.author.id, opts))
    except Exception:
        log.debug("Data choices skipped", exc_info=True)


async def slip_review(client, guild_id: int, asker, slip: dict, question: str) -> tuple[str, Optional[discord.File]]:
    """The written take plus the X-ray image (None when no leg has a game log)."""
    try:
        data = await slip_xray_data(slip)
    except Exception:
        log.warning("X-ray data failed", exc_info=True)
        data = []
    try:
        inj = await xray_injuries(data)
    except Exception:
        log.warning("Injury check for the breakdown failed", exc_info=True)
        inj = {}
    try:
        slip["_xray"] = data
    except Exception:
        pass
    text = await slip_review_text(client, guild_id, asker, slip, question, xray_notes(data), data=data, injuries=inj)
    try:
        note_scouted(guild_id, asker.id, [x["name"] for x in data if x.get("values")])
    except Exception:
        pass
    f = None
    try:
        f = await slip_xray_file(slip, data)
    except Exception:
        log.warning("X-ray image failed", exc_info=True)
    return text, f


async def slip_review_text(client, guild_id: int, asker, slip: dict, question: str,
                           extra: Optional[list] = None, data: Optional[list] = None,
                           injuries: Optional[dict] = None) -> str:
    legs = [str(x).strip() for x in (slip.get("legs") or []) if str(x).strip()]
    lines = [f"Question from {asker.display_name}: {question.strip() or 'What do you think of this slip?'}",
             f"The slip: {slip.get('platform') or '?'} · {slip.get('description') or ''}"
             + (f" · {slip.get('sport')}" if slip.get("sport") else "")
             + (f" · {money(slip['cost'])} to win {money(slip['payout'])}" if slip.get("cost") and slip.get("payout") else "")
             + ("" if slip.get("placed", True) else " · not placed yet"),
             "Legs:"] + [f"{k}. {leg}" for k, leg in enumerate(legs, 1)]
    notes = []
    key = str(asker.id)
    for leg in legs[:8]:
        pr = cached_prop(leg)
        if not pr:
            continue
        mine = run_group_stats(guild_id, key, {"bettor": "me", "player": pr["display"]})
        grp = run_group_stats(guild_id, key, {"player": pr["display"]})
        side = run_group_stats(guild_id, key, {"bettor": "me", "stat": STATS[pr["stats"][0]][0], "side": pr["side"]})
        for label, r in ((f"{asker.display_name}'s legs on {pr['display']}", mine),
                         (f"the group's legs on {pr['display']}", grp),
                         (f"{asker.display_name}'s {STATS[pr['stats'][0]][0]} {pr['side']}s", side)):
            g = (r.get("groups") or [None])[0]
            if g and g.get("hit", 0) + g.get("miss", 0) >= 3:
                notes.append(f"- {label}: hit {g['hit']} of {g['hit'] + g['miss']}")
    if extra:
        lines += ["", "Each player's last games against this number (from ESPN game logs):"] + extra
    if injuries:
        lines += ["", "Injury report right now:"] + [
            f"- {n}: {v.get('status')}" + (f" ({clip(v['comment'], 140)})" if v.get("comment") else "")
            for n, v in injuries.items()]
    if notes:
        lines += ["", "The group's own history:"] + list(dict.fromkeys(notes))[:12]
    group_notes = list(dict.fromkeys(notes))
    if not ask_enabled():
        return numbers_breakdown(data or [], injuries, group_notes) + "\n-# Not logged. Tap 🧾 to file it. Staff can put it under someone else."
    system = ASK_SYSTEM.format(bot_name=getattr(getattr(client, "user", None), "display_name", "PIMP-BOT"),
                               today=datetime.now(TZ).strftime("%A, %B %d, %Y"))
    system += f"\n\nYour voice in this server: {persona_prompt(guild_id)}.\n\n" + REVIEW_RULES
    system += ("\n\nYou can't search the web for this one: base every leg only on the game logs, injury report and "
               "group history in the message. If a leg has no numbers there, say so instead of guessing.")
    if slip.get("status") in ("win", "loss", "push"):
        system += ("\n\nThis card is already settled as a " + slip["status"]
                   + ". Lead with that result and the players on it. Do not say pass, and do not rate it as a bet "
                   "still to make. A missing game log is one short clause, not the answer.")
    else:
        system += ("\n\nUse one mark per leg, not two. If a player has no game log, name them and the line and move on. "
                   "Do not repeat a no-log sentence for every leg.")
    ctx = {"guild_id": guild_id, "asker_key": key, "chart": None}
    token = ASK_DATA.set(ctx)
    try:
        answer, sources = await ask_any(system, "\n".join(lines), search=False)
    except Exception as exc:
        log.warning("Slip review failed: %s", str(exc)[:200])
        why = ASK_LAST_ERROR.get("text") or ask_error_hint(exc)
        return (numbers_breakdown(data or [], injuries, group_notes)
                + f"\n-# The AI write-up is off right now ({clip(why, 220)}), so these are the straight numbers. "
                  "Not logged. Tap 🧾 to file it. Staff can put it under someone else.")
    finally:
        ASK_DATA.reset(token)
    answer = review_scrub(answer)
    if sources:
        answer += "\n\n-# Sources: " + " · ".join(f"<{u}>" for u in sources)
    return (answer or "I came up empty on that one.") + "\n-# Not logged. Tap 🧾 to file it. Staff can put it under someone else."


_SURE_TALK = re.compile(r"\b(?:essentially |basically |practically |pretty much |almost )?(?:a )?(?:sure[- ]thing|"
                        r"lock|lead[- ]pipe lock|guarantee[ds]?|free money|can'?t[- ]miss|easy money|no[- ]brainer)\b", re.I)


def review_scrub(text: str) -> str:
    """Takes 'sure thing' talk out of an AI write-up: past games are a trend, not a promise."""
    text = _SURE_TALK.sub("a strong recent trend", text or "")
    return re.sub(r";?\s*consider (?:swapping or )?hedging[^.\n]*", "", text)


# --------------------------------------------------------------------------
# Claude: reading slips and answering questions (needs ANTHROPIC_API_KEY)
# --------------------------------------------------------------------------

IMAGE_TYPES = {"image/jpeg", "image/png", "image/gif", "image/webp", "image/bmp", "image/tiff",
               "image/heic", "image/heif", "image/avif"}
IMAGE_EXTS = {".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".png": "image/png", ".gif": "image/gif",
              ".webp": "image/webp", ".bmp": "image/bmp", ".tif": "image/tiff", ".tiff": "image/tiff",
              ".heic": "image/heic", ".heif": "image/heif", ".avif": "image/avif"}
SLIP_MAX_PICS = 12                # every picture on a message (Discord's practical cap is well under this)
SLIP_STATE = {"last_error": None, "last_ok": None}


def image_type(attachment) -> Optional[str]:
    """The image's media type, or None if it isn't a picture Claude can read. Discord sometimes leaves
    content_type empty (and phones send image/jpg), so fall back to the file name."""
    ct = (getattr(attachment, "content_type", None) or "").split(";")[0].strip().lower()
    if ct == "image/jpg":
        ct = "image/jpeg"
    if ct in IMAGE_TYPES:
        return ct
    name = (getattr(attachment, "filename", None) or getattr(attachment, "url", None) or "").lower().split("?")[0]
    for ext, t in IMAGE_EXTS.items():
        if name.endswith(ext):
            return t
    return None


def image_attachments(message) -> list:
    return [a for a in (getattr(message, "attachments", None) or []) if image_type(a)]
MAX_IMAGE_BYTES = 7 * 1024 * 1024  # stays under the API's limit once base64-encoded


def slip_shot_dir() -> str:
    """Folder next to the database. The scanned screenshot lives here, not in the pick row."""
    folder = os.path.join(os.path.dirname(os.path.abspath(DB_PATH)) or ".", "slip-shots")
    os.makedirs(folder, exist_ok=True)
    return folder


def _slip_shot_write(path: str, raw: bytes) -> None:
    """Write the photo once. A file that already has bytes is left alone."""
    if not raw or len(raw) > MAX_IMAGE_BYTES:
        return
    try:
        if os.path.getsize(path) > 0:
            return
    except OSError:
        pass
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".part"
    with open(tmp, "wb") as fh:
        fh.write(raw)
    os.replace(tmp, path)


def slip_shot_stash_path(message_id: int, attachment_id: int) -> str:
    return os.path.join(slip_shot_dir(), f"m{int(message_id)}-{int(attachment_id)}.img")


def slip_shot_pick_path(pick_id: int) -> str:
    return os.path.join(slip_shot_dir(), f"p{int(pick_id)}.img")


async def keep_slip_photo(attachment, message_id: int) -> None:
    """Save the screenshot the first time we see it. Later reads and receipt refreshes use this copy."""
    aid = getattr(attachment, "id", None)
    if not message_id or not aid:
        return
    path = slip_shot_stash_path(message_id, aid)
    try:
        if os.path.getsize(path) > 0:
            return
    except OSError:
        pass
    if (getattr(attachment, "size", 0) or 0) > MAX_IMAGE_BYTES:
        return
    try:
        raw = await attachment.read()
    except Exception:
        log.warning("Could not keep the slip photo", exc_info=True)
        return
    _slip_shot_write(path, raw)


def bind_slip_shot(pick_id: int, message_id: Optional[int] = None, attachment_id: Optional[int] = None,
                   n_legs: Optional[int] = None) -> None:
    """Copy the saved screenshot onto this pick, then cut the player photos out of it once."""
    dest = slip_shot_pick_path(pick_id)
    raw = None
    try:
        if os.path.getsize(dest) > 0:
            with open(dest, "rb") as fh:
                raw = fh.read()
    except OSError:
        raw = None
    if not raw:
        src = None
        if message_id and attachment_id:
            cand = slip_shot_stash_path(message_id, attachment_id)
            try:
                if os.path.getsize(cand) > 0:
                    src = cand
            except OSError:
                src = None
        if src is None and message_id:
            prefix = f"m{int(message_id)}-"
            try:
                hits = sorted(name for name in os.listdir(slip_shot_dir())
                              if name.startswith(prefix) and name.endswith(".img"))
            except OSError:
                hits = []
            if hits:
                src = os.path.join(slip_shot_dir(), hits[0])
        if not src:
            return
        try:
            with open(src, "rb") as fh:
                raw = fh.read()
        except OSError:
            return
        _slip_shot_write(dest, raw)
    save_player_faces(pick_id, raw, n_legs)


def slip_face_path(pick_id: int, idx: int) -> str:
    return os.path.join(slip_shot_dir(), f"p{int(pick_id)}-{int(idx)}.png")


def prizepicks_player_faces(raw: bytes, limit: Optional[int] = None) -> list[bytes]:
    """Player photos down a PrizePicks slip, top to bottom, as square PNGs.

    One pass over the screenshot. The circles sit in a column on the left of each leg.
    A later refresh reads the saved files and does not look at the screenshot again."""
    import math
    from collections import deque
    from PIL import Image
    try:
        im = Image.open(io.BytesIO(raw)).convert("RGB")
    except Exception:
        return []
    w, h = im.size
    if w < 80 or h < 120:
        return []
    tw = 360
    scale = tw / w
    small = im.resize((tw, max(1, int(h * scale))), Image.BILINEAR)
    sw, sh = small.size
    pix = small.load()

    def lum(p) -> float:
        return 0.3 * p[0] + 0.59 * p[1] + 0.11 * p[2]

    def chroma(p) -> int:
        return max(p) - min(p)

    def purple(p) -> bool:
        return p[0] > 80 and p[2] > 100 and p[1] < p[0] * 0.8

    ink = bytearray(sw * sh)
    for y in range(sh):
        row = y * sw
        for x in range(sw):
            p = pix[x, y]
            if lum(p) > 36 or chroma(p) > 18:
                ink[row + x] = 1
    seen = bytearray(sw * sh)
    comps = []
    for y in range(sh):
        for x in range(int(sw * 0.48)):
            i = y * sw + x
            if not ink[i] or seen[i]:
                continue
            q = deque([(x, y)])
            seen[i] = 1
            pts = 0
            minx = maxx = x
            miny = maxy = y
            cols = []
            while q:
                cx, cy = q.popleft()
                pts += 1
                if pts % 3 == 0 and len(cols) < 500:
                    cols.append(pix[cx, cy])
                if cx < minx:
                    minx = cx
                if cx > maxx:
                    maxx = cx
                if cy < miny:
                    miny = cy
                if cy > maxy:
                    maxy = cy
                for nx, ny in ((cx - 1, cy), (cx + 1, cy), (cx, cy - 1), (cx, cy + 1)):
                    if 0 <= nx < sw and 0 <= ny < sh:
                        j = ny * sw + nx
                        if ink[j] and not seen[j]:
                            seen[j] = 1
                            q.append((nx, ny))
            bw, bh = maxx - minx + 1, maxy - miny + 1
            if pts < 60 or bw < 10 or bh < 10:
                continue
            aspect = bw / max(1, bh)
            if not (0.7 <= aspect <= 1.4) or pts / (bw * bh) < 0.42:
                continue
            cx = (minx + maxx) / 2
            if cx > sw * 0.42:
                continue
            purp = sum(1 for p in cols if purple(p)) / len(cols) if cols else 0
            comps.append({"cx": cx, "cy": (miny + maxy) / 2, "bh": bh, "purple": purp})
    people = [c for c in comps if c["purple"] < 0.42]
    best = []
    for c in people:
        group = [o for o in people if abs(o["cx"] - c["cx"]) <= 10 and 0.7 <= o["bh"] / c["bh"] <= 1.4]
        if len(group) > len(best):
            best = group
    if len(best) < 2:
        return []
    xs = sorted(o["cx"] for o in best)
    hs = sorted(o["bh"] for o in best)
    col_x = xs[len(xs) // 2]
    radius = max(10.0, hs[len(hs) // 2] / 2)
    angs = [(math.cos(i * math.tau / 16), math.sin(i * math.tau / 16)) for i in range(16)]
    series = []
    y = int(radius + 2)
    while y < sh - radius - 2:
        ins, outs = [], []
        for ca, sa in angs:
            ix = max(0, min(sw - 1, int(col_x + (radius - 1) * ca)))
            iy = max(0, min(sh - 1, int(y + (radius - 1) * sa)))
            ox = max(0, min(sw - 1, int(col_x + (radius + 3) * ca)))
            oy = max(0, min(sh - 1, int(y + (radius + 3) * sa)))
            ins.append(pix[ix, iy])
            outs.append(pix[ox, oy])
        il = sum(lum(p) for p in ins) / len(ins)
        ol = sum(lum(p) for p in outs) / len(outs)
        dark = sum(1 for p in outs if lum(p) < 70) / len(outs)
        score = (il - ol) if dark >= 0.66 and il >= 32 else 0
        series.append((y, max(0.0, score)))
        y += 2
    peaks = []
    for i in range(1, len(series) - 1):
        if series[i][1] >= 12 and series[i][1] >= series[i - 1][1] and series[i][1] >= series[i + 1][1]:
            yy, sc = series[i]
            if peaks and yy - peaks[-1][0] < radius * 2.05:
                if sc > peaks[-1][1]:
                    peaks[-1] = (yy, sc)
                continue
            peaks.append((yy, sc))
    found = []
    r2 = (radius * 0.9) ** 2
    for yy, sc in peaks:
        if sc < 15:
            continue
        base_lums = []
        for ca, sa in angs:
            ox = max(0, min(sw - 1, int(col_x + (radius + 3) * ca)))
            oy = max(0, min(sh - 1, int(yy + (radius + 3) * sa)))
            base_lums.append(lum(pix[ox, oy]))
        base = sorted(base_lums)[len(base_lums) // 2]
        bright = total = purp = 0
        for dy in range(-int(radius), int(radius) + 1, 2):
            for dx in range(-int(radius), int(radius) + 1, 2):
                if dx * dx + dy * dy > r2:
                    continue
                p = pix[max(0, min(sw - 1, int(col_x + dx))), max(0, min(sh - 1, int(yy + dy)))]
                total += 1
                if lum(p) > base + 16 or chroma(p) > 26:
                    bright += 1
                if purple(p):
                    purp += 1
        if not total:
            continue
        found.append({"y": yy, "score": sc, "fill": bright / total, "purple": purp / total})
    usable = [c for c in found if c["purple"] < 0.40]
    highs = sorted((c["fill"] for c in usable if c["fill"] >= 0.40), reverse=True)
    if not highs:
        return []
    bar = 0.62 if highs[len(highs) // 2] >= 0.68 else 0.42
    kept = [c for c in usable if c["fill"] >= bar]
    cap = limit if limit and limit > 0 else 12
    if len(kept) > cap:
        drop = set(sorted(range(len(kept)), key=lambda i: kept[i]["score"])[:len(kept) - cap])
        kept = [c for i, c in enumerate(kept) if i not in drop]
    out = []
    for c in kept[:12]:
        cx, cy, rr = col_x / scale, c["y"] / scale, radius / scale
        box = (int(cx - rr), int(cy - rr), int(cx + rr), int(cy + rr))
        crop = im.crop(box)
        if min(crop.size) < 8:
            continue
        buf = io.BytesIO()
        crop.save(buf, format="PNG")
        out.append(buf.getvalue())
    return out


def save_player_faces(pick_id: int, raw: bytes, n_legs: Optional[int] = None) -> None:
    """Write each player photo once. A pick that already has the first photo is left alone."""
    first = slip_face_path(pick_id, 1)
    try:
        if os.path.getsize(first) > 0:
            return
    except OSError:
        pass
    for i, png in enumerate(prizepicks_player_faces(raw, n_legs), start=1):
        _slip_shot_write(slip_face_path(pick_id, i), png)


def with_slip_faces(pick_id: int, entries: list) -> list:
    """Copies of the legs with the saved PrizePicks player photo on slip_face, in leg order."""
    faces = []
    for i in range(1, 17):
        try:
            with open(slip_face_path(pick_id, i), "rb") as fh:
                raw = fh.read()
        except OSError:
            break
        if not raw:
            break
        faces.append(raw)
    if not faces:
        return entries
    order = sorted(range(len(entries)), key=lambda i: (entries[i].get("n") is None, entries[i].get("n") or 0))
    out = [dict(e) for e in entries]
    for face, i in zip(faces, order):
        out[i]["slip_face"] = face
    return out

SLIP_PROMPT = """This is a screenshot posted in a sports betting group. If it shows a \
bet slip, entry, or position (PrizePicks, Kalshi, a sportsbook, etc.), extract it.

Reply with ONLY a JSON object, no other text:
{
  "is_slip": true or false,
  "platform": "PrizePicks" | "Kalshi" | the sportsbook name | "Other",
  "sport": short sport/league name or null,
  "description": one short line summarizing the play, e.g. "6-pick Power Play" or "5-pick Flex Play" or "3-leg NFL combo",
  "legs": ["one string per leg. Player props as 'Player Name over|under LINE stat' (PrizePicks More = over, \
Less = under), e.g. 'Victor Wembanyama over 23.5 Pts+Rebs+Asts'. Game lines as 'Chiefs ML', 'Chiefs -3.5', \
'Over 44.5'"],
  "cost": number risked (entry fee / stake / cost) or null if not visible,
  "payout": total amount paid back if it wins (or that it did pay), or null if not visible,
  "status": "open" | "win" | "loss" | "push",
  "returned": amount actually paid out if the slip is already settled, else null,
  "game_date": "YYYY-MM-DD" date of the earliest game on the slip when it shows game days or times \
(e.g. "Thu 7:30pm", "Oct 8", "Today"), else null,
  "entry_type": "power" | "flex" | null (PrizePicks Power Play or Underdog Standard = power; Flex Play or \
Insured = flex),
  "placed": true if this entry/bet was actually submitted (an entry or bet ID, "Entry placed", "My Bets"/"My \
Entries" view, live progress or a result); false if it is still being built (an entry-fee box, "Place Entry", \
"Submit", "Deposit Funds", "Add to betslip", "Not enough balance", empty pick slots)
}

Use "open" unless the screenshot clearly shows a final result. A win picture \
(a won banner, cashed, "you won", or a payout already paid) is "win", and "returned" is that paid amount when it is on the screen. \
A loss picture (a lost banner, "you lost", entry lost, or busted) is "loss", and "returned" is 0. \
A parlay still in progress, pending, or waiting on its games is "open". Do not invent a result. \
"to win" on an entry that is still open is the possible payout, not a win. \
Numbers must be plain numbers with no currency symbols. Never guess an amount you cannot read.

PrizePicks details: the header reads like "$25 to win $450" (cost 25, payout 450). If a line \
shows a crossed-out number next to a new number (a discounted or promo line), the leg uses the \
NEW number, never the crossed-out one. Demon and goblin icons don't change how you write the leg. \
Up arrow = over, down arrow = under. Keep accents and spelling of player names exactly as shown. \
Every card is its own leg, including NHL SOG, MLB Hitter FS and Singles, tennis Total Tie Breaks, Total Games \
and Fantasy Score, darts 180's Throw, cricket Fours and Sixes, and table tennis Total Points. NBAP means NBA. \
Do not drop a leg because the sport is tennis, darts, cricket, or table tennis.

Copy each stat name exactly as the slip shows it ("Punts" is not "Points"; "Faceoffs Won", "Fantasy Score", \
"Longest Rec"). A two-player combo is written "Player A + Player B over LINE stat (Combo)". \
NBASZN is NBA and NFLSZN is NFL. PPG, RPG, APG, BPG, 3PTM, 3PTA, FTM, and 50+ Point Games are real stats. \
A green More button is over and a green Less button is under. If you can't read \
the individual picks, still return what you can, never a placeholder like "6 Pick Power Play" as a leg."""

ASK_SYSTEM = """You are {bot_name}, the assistant in a Discord server where a group of \
friends track their sports picks (Kalshi, PrizePicks and sportsbooks; NFL, CS2 esports \
and more). People @mention you with questions about players, teams, matchups, form, \
injuries and roster news.

Search the web for anything current, like recent results, injuries, lineups and rosters. \
Today is {today}.

How to answer:
- This is Discord: keep it under about 200 words. Lead with the direct answer, then the \
two or three facts that matter most. Short bullets are fine; no headings.
- Focus on players, form and matchups. Don't narrate line or odds movements unless asked.
- Be straight about uncertainty and thin information. Never call anything a lock or \
promise an outcome.
- The group's own scouting notes and records are included below when relevant. Use them, \
and say when you're relying on them.
- Sports questions of every kind are in scope: scores, who plays, schedules, injuries, form, and weather. \
When the message includes a weather block, quote those numbers, the game, and the city where they play. \
Do not say a chart cannot be shown. Do not invent a temperature.
- Any other question is in scope too. News, how something works, a definition, a plan, math, history, \
or a normal chat: answer that question. Do not turn it into a sports take, and do not say you only \
handle picks or scores.
- When a fact could have changed, or you are not sure, say what you know and what you are unsure about. \
Search before you guess at something current."""

_anthropic = None


def ai_enabled() -> bool:
    return bool(ANTHROPIC_API_KEY)


vision_enabled = ai_enabled  # kept for older references


def anthropic_client():
    global _anthropic
    if _anthropic is None:
        import anthropic  # imported lazily so the bot runs without it
        _anthropic = counted_client(anthropic.AsyncAnthropic(api_key=ANTHROPIC_API_KEY))
    return _anthropic


def extract_json(text: str) -> dict:
    match = re.search(r"\{.*\}", text, re.S)
    if not match:
        raise ValueError("no JSON in model reply")
    return json.loads(match.group(0))


def as_amount(value) -> Optional[float]:
    """Coerce a model-supplied number; None if missing or unusable."""
    if value is None or isinstance(value, bool):
        return None
    try:
        return parse_money(str(value))
    except ValueError:
        return None


VISION_MAX_EDGE = 1568        # Claude shrinks anything bigger than this, so enlarge up to it and no further
VISION_MAX_PIXELS = 1_150_000


def _fit(img, max_edge: int = VISION_MAX_EDGE, max_px: int = VISION_MAX_PIXELS):
    """Scale up (or down) so the image is as big as Claude will actually look at."""
    from PIL import Image
    w, h = img.size
    scale = min(max_edge / max(w, h), (max_px / (w * h)) ** 0.5)
    if abs(scale - 1) < 0.05:
        return img
    return img.resize((max(1, round(w * scale)), max(1, round(h * scale))), Image.LANCZOS)


def enlarge_slip(raw: bytes) -> list[bytes]:
    """PNG images to send: the whole slip enlarged, plus zoomed, overlapping slices of tall phone screenshots
    so small print (lines, stat names, the cost) is big enough to read. Falls back to the original on any error."""
    from PIL import Image, ImageFilter, ImageOps
    img = Image.open(io.BytesIO(raw))
    sec_check_image(img)                          # before decoding: refuse decompression bombs
    img.seek(0)                                   # first frame of a GIF
    img = ImageOps.exif_transpose(img).convert("RGB")
    out = [_fit(img)]
    w, h = img.size
    if h > 1.4 * w:                               # tall screenshot: slice it, each slice a bit taller than wide
        n = min(4, max(2, math.ceil(h / (w * 0.8))))   # shorter slices = more zoom
        step = h / n
        pad = int(step * 0.12)                    # overlap so no row gets cut in half
        for i in range(n):
            top, bottom = max(0, int(i * step) - pad), min(h, int((i + 1) * step) + pad)
            out.append(_fit(img.crop((0, top, w, bottom))))
    pngs = []
    for im in out:
        im = im.filter(ImageFilter.UnsharpMask(radius=1.2, percent=60, threshold=2))
        buf = io.BytesIO()
        im.save(buf, "PNG", optimize=True)
        pngs.append(buf.getvalue())
    return pngs


def sniff_image_type(raw: bytes) -> Optional[str]:
    """What the bytes really are. Phones and Discord often label a JPEG or WebP as PNG, which Claude rejects."""
    if raw[:8] == b"\x89PNG\r\n\x1a\n":
        return "image/png"
    if raw[:3] == b"\xff\xd8\xff":
        return "image/jpeg"
    if raw[:6] in (b"GIF87a", b"GIF89a"):
        return "image/gif"
    if raw[:4] == b"RIFF" and raw[8:12] == b"WEBP":
        return "image/webp"
    if raw[:2] == b"BM":
        return "image/bmp"
    if raw[:4] in (b"II*\x00", b"MM\x00*"):
        return "image/tiff"
    return None


async def read_slip(attachment: discord.Attachment, model: Optional[str] = None) -> Optional[dict]:
    """Returns the parsed slip, or None if it couldn't be read as one."""
    sec_check_attachment(attachment)
    raw = await attachment.read()
    if len(raw) > MAX_IMAGE_BYTES:
        raise SecImageTooBig(f"{len(raw) // 1024} KB")
    try:
        pngs = await asyncio.to_thread(enlarge_slip, raw)
        images = [("image/png", p) for p in pngs]
    except Exception:
        log.warning("Couldn't enlarge the slip image; sending it as is", exc_info=True)
        images = [(sniff_image_type(raw) or image_type(attachment) or "image/png", raw)]
    content = [{"type": "image", "source": {"type": "base64", "media_type": mt,
                                            "data": base64.standard_b64encode(b).decode()}} for mt, b in images]
    prompt = SLIP_PROMPT
    if len(images) > 1:
        prompt = (f"These {len(images)} images are ONE screenshot: the first is the whole thing, the rest are "
                  "enlarged slices of it from top to bottom that overlap a little. Use the slices to read small "
                  "text, and count each leg only once.\n\n" + SLIP_PROMPT)
    prompt += (f"\n\nToday is {datetime.now(TZ):%A, %B %d, %Y} ({TZ}). Game days shown on a slip are "
               "within the past week or the coming week.")
    content.append({"type": "text", "text": prompt})
    reply = await asyncio.wait_for(anthropic_client().messages.create(
        model=model or CLAUDE_MODEL,
        max_tokens=1500,
        messages=[{"role": "user", "content": content}],
    ), timeout=12)
    text = "".join(block.text for block in reply.content if block.type == "text")
    slip = extract_json(text)
    if not slip.get("is_slip"):
        return None
    slip["cost"] = as_amount(slip.get("cost"))
    slip["payout"] = as_amount(slip.get("payout"))
    slip["returned"] = as_amount(slip.get("returned"))
    if slip.get("status") not in ("open", "win", "loss", "push"):
        slip["status"] = "open"
    slip["placed"] = slip.get("placed") is not False
    return slip


_CLAUDE_DEAD_UNTIL: Optional[float] = None


def claude_alive() -> bool:
    """False for a few hours after Anthropic says the account is out of credits, so we don't wait on it again."""
    global _CLAUDE_DEAD_UNTIL
    if _CLAUDE_DEAD_UNTIL is None:
        try:
            raw = get_setting(0, "claude_dead_until") or ""
            _CLAUDE_DEAD_UNTIL = float(raw) if raw else 0.0
        except Exception:
            _CLAUDE_DEAD_UNTIL = 0.0
    return time.time() >= _CLAUDE_DEAD_UNTIL


def claude_mark_dead(hours: float = 6) -> None:
    global _CLAUDE_DEAD_UNTIL
    _CLAUDE_DEAD_UNTIL = time.time() + hours * 3600
    try:
        set_setting(0, "claude_dead_until", str(int(_CLAUDE_DEAD_UNTIL)))
    except Exception:
        pass


def explain_ai_error(exc: Exception) -> tuple[str, bool]:
    """(plain-English reason, worth retrying with another model?)"""
    name = type(exc).__name__
    text = str(exc).lower()
    if "credit balance" in text or "billing" in text:
        claude_mark_dead()
        return "the Anthropic account is out of credits (console.anthropic.com → Billing)", False
    if name == "AuthenticationError" or "x-api-key" in text or "authentication" in text:
        return "the Claude key was rejected. Put a working key in `ANTHROPIC_API_KEY` on Railway → Variables", False
    if name == "PermissionDeniedError":
        return "that Claude key isn't allowed to use this model", True
    if name == "NotFoundError" or "not_found" in text or "model:" in text:
        return "the model name isn't valid. Remove or fix the `CLAUDE_MODEL` variable on Railway", True
    if name == "RateLimitError" or "rate limit" in text:
        return "Claude is rate-limiting the key right now; try again in a minute", False
    if name in ("APIConnectionError", "APITimeoutError", "InternalServerError") or "overloaded" in text:
        return "Claude was unreachable or overloaded; try again in a minute", True
    if "media_type" in text or "image" in text and name == "BadRequestError":
        return "Claude couldn't open that image file. Try a fresh screenshot (PNG or JPG)", True
    if name in ("JSONDecodeError", "ValueError"):
        return "Claude's answer wasn't in the expected format", True
    if name == "SecImageTooBig":
        return "the image is too big to read. Send a normal screenshot (under 7 MB)", False
    return f"something unexpected went wrong ({name}); try again in a minute", True


async def read_slip_claude(attachment) -> tuple[Optional[dict], Optional[str]]:
    """Read with Claude's fast model; if that fails or misses the amounts, try once more with the stronger one.
    Returns (slip or None, reason it failed or None)."""
    if not claude_alive():
        return None, "the Anthropic account is out of credits (console.anthropic.com → Billing)"
    reason = None
    models = [None] + ([ASK_MODEL] if ASK_MODEL and ASK_MODEL != CLAUDE_MODEL else [])
    for i, model in enumerate(models):
        try:
            slip = await (read_slip(attachment) if model is None else read_slip(attachment, model=model))
        except Exception as exc:
            log.exception("Could not read slip %s with %s", getattr(attachment, "url", "?"), model or CLAUDE_MODEL)
            reason, retry = explain_ai_error(exc)
            SLIP_STATE["last_error"] = (now_iso(), f"Reading with Claude: {type(exc).__name__}: {exc}"[:300])
            if not retry:
                return None, reason
            continue
        if slip is None:
            reason = "it didn't look like a bet slip to me"
            continue
        if slip.get("cost") is None:
            reason = "I couldn't make out the amount risked"
            if i == len(models) - 1:
                return slip, reason
            continue
        return slip, None
    return None, reason


def build_ask_context(guild_id: int, asker_key: str, question: str) -> str:
    """The group's own data that's relevant to this question."""
    parts = []
    q = player_key(question)
    matched = [p for p in db().execute("SELECT * FROM players WHERE guild_id = ?", (guild_id,))
               if re.search(rf"(?<!\w){re.escape(p['name_key'])}(?!\w)", q)][:5]
    for p in matched:
        meta = " · ".join(x for x in (p["team"], p["sport"], p["role"]) if x)
        lines = [f"Tracked player: {p['name']}" + (f" ({meta})" if meta else "")]
        for n in player_notes(p["id"], 8):
            lines.append(f"  - {local_day(n['created_at'])}, {n['author_name']}: {n['text']}")
        rate = hit_rate(leg_counts(guild_id, text_like=p["name"]))
        if rate:
            lines.append(f"  - The group's legs on this player: {rate}")
        parts.append("\n".join(lines))
    stats = compute_stats(guild_id, asker_key)
    if stats:
        s = stats[0]
        parts.append(f"The person asking ({s['name']}) is {record_line(s)}, "
                     f"net {signed(s['net'])}, ROI {s['roi']:+.1f}%, {s['open']} picks open.")
    try:
        opens = db().execute("SELECT COUNT(*) AS n FROM picks WHERE guild_id = ? AND status = 'open'",
                             (guild_id,)).fetchone()["n"]
        parts.append(f"Open slips in this group right now: {opens}.")
        leaders = compute_stats(guild_id)[:3]
        if leaders:
            bits = [f"{s['name']} {record_line(s)} net {signed(s['net'])}" for s in leaders]
            parts.append("Season board, best net first: " + "; ".join(bits) + ".")
        if re.search(r"\b(tonight|open|slate|my slips|my picks|my open|what'?s on|whats on)\b", question or "", re.I):
            mine = bool(re.search(r"\b(my slips|my picks|my open)\b", question or "", re.I))
            sql = ("SELECT bettor_name, description, legs FROM picks WHERE guild_id = ? AND status = 'open'")
            args: list = [guild_id]
            if mine:
                sql += " AND bettor_key = ?"
                args.append(asker_key)
            sql += " ORDER BY id DESC LIMIT 6"
            rows = db().execute(sql, args).fetchall()
            bits = []
            for r in rows:
                first = ((r["legs"] or "").split("\n")[0] or "").strip()[:80]
                line = f"{r['bettor_name']}: {r['description']}"
                if first:
                    line += f" · {first}"
                bits.append(line)
            if bits:
                label = "This person's open slips" if mine else "Open slips (newest first)"
                parts.append(label + ": " + " | ".join(bits) + ".")
            elif mine:
                parts.append("This person has no open slips right now.")
    except Exception:
        pass
    return "\n\n".join(parts)


async def ask_claude(system: str, user_text: str, max_searches: int = 5) -> tuple[str, list[str]]:
    """Returns (answer text, source urls). When ASK_DATA is set, Claude can also query the group's own records."""
    ctx = ASK_DATA.get()
    base = [{"role": "user", "content": user_text}]
    messages = base
    tools = [{"type": "web_search_20250305", "name": "web_search", "max_uses": max_searches}]
    if ctx is not None:
        tools.append(DATA_TOOL)
    reply = None
    pending: list = []
    seen_blocks: list = []
    lookups = 0
    for _ in range(8):  # long searches can pause, and data lookups take a round trip each
        reply = await asyncio.wait_for(anthropic_client().messages.create(
            model=ASK_MODEL, max_tokens=1500, system=system, messages=messages, tools=tools), timeout=SEC_CLAUDE_TIMEOUT)
        seen_blocks.extend(getattr(reply, "content", None) or [])
        if reply.stop_reason == "pause_turn":
            pending = pending + list(reply.content)
            messages = base + [{"role": "assistant", "content": pending}]
            continue
        if reply.stop_reason == "tool_use" and ctx is not None:
            results = []
            for b in reply.content:
                if getattr(b, "type", "") == "tool_use" and getattr(b, "name", "") == "group_stats":
                    args = dict(getattr(b, "input", None) or {})
                    try:
                        res = run_group_stats(ctx["guild_id"], ctx["asker_key"], args)
                    except Exception as exc:
                        log.exception("group_stats failed")
                        res = {"error": sec_redact(f"{type(exc).__name__}: {exc}")[:300]}
                    if args.get("chart"):
                        ch = chart_from_result(res)
                        if ch:
                            ctx["chart"] = ch
                    lookups += 1
                    if lookups >= 5:
                        res["note"] = "That's the last lookup; answer now with what you have."
                    while len(json.dumps(res, default=str)) > 12000 and len(res.get("groups") or []) > 1:
                        res["groups"] = res["groups"][:-1]
                    results.append({"type": "tool_result", "tool_use_id": b.id,
                                    "content": json.dumps(res, default=str)})
            if not results:
                break
            base = base + [{"role": "assistant", "content": pending + list(reply.content)},
                           {"role": "user", "content": results}]
            messages, pending = base, []
            continue
        break
    final_blocks = pending if reply.stop_reason == "pause_turn" else pending + list(reply.content)
    text = "".join(b.text for b in final_blocks if getattr(b, "type", "") == "text").strip()
    sources: list[str] = []
    for b in seen_blocks:
        for c in (getattr(b, "citations", None) or []):
            url = getattr(c, "url", None)
            if url and url not in sources:
                sources.append(url)
    return text, sources[:3]


# --------------------------------------------------------------------------
# Free result lookups: ESPN's public scoreboard, for moneylines, spreads and totals.
# Anything else (player props, halves, esports, tennis) falls through to Claude.
# --------------------------------------------------------------------------

ESPN = "https://site.api.espn.com/apis/site/v2/sports/{path}/scoreboard"
LEAGUES = [  # (pattern in the pick's sport, ESPN path, extra query params)
    (r"\bwnba\b", "basketball/wnba", {}),
    (r"\bnfl(?:szn)?\b", "football/nfl", {}),
    (r"ncaa ?f|college football|\bncaaf\b|\bcfb\b", "football/college-football", {"groups": "80"}),
    (r"\b(?:nba(?:szn|p)?|nbap)\b", "basketball/nba", {}),
    (r"ncaa ?b|college basketball|\bncaab\b|\bcbb\b", "basketball/mens-college-basketball", {"groups": "50"}),
    (r"\bmlb\b|baseball", "baseball/mlb", {}),
    (r"\bnhl\b|hockey", "hockey/nhl", {}),
    (r"\bmls\b", "soccer/usa.1", {}),
    (r"\bepl\b|premier league", "soccer/eng.1", {}),
    (r"la ?liga", "soccer/esp.1", {}),
    (r"serie a", "soccer/ita.1", {}),
    (r"bundesliga", "soccer/ger.1", {}),
    (r"ligue 1", "soccer/fra.1", {}),
    (r"liga ?mx", "soccer/mex.1", {}),
    (r"champions league|\bucl\b", "soccer/uefa.champions", {}),
]
NO_FREE_LOOKUP = r"esports|\bcs2?\b|counter|valorant|league of legends|dota|tennis|\bwta\b|\batp\b|golf|ufc|mma|boxing|f1|nascar|politic|crypto"
DEFAULT_LEAGUES = ["football/nfl", "basketball/nba", "baseball/mlb", "hockey/nhl", "football/college-football"]
NOT_SIMPLE = re.compile(
    r"\b(1h|2h|1q|2q|3q|4q|half|quarters?|innings?|periods?|sets?|maps?|rounds?|first|1st|2nd|3rd|4th|"
    r"yards?|yds|tds?|touchdowns?|receptions?|rec|rush|rushing|passing|pass|kills|rating|assists?|"
    r"rebounds?|strikeouts?|hits|shots|corners|cards|sacks|interceptions?|threes|3-pointers|"
    r"tie|draw|btts|both teams|anytime|scorer|race to|double|triple|exact|correct score|alt)\b", re.I)

_score_cache: dict[tuple[str, str], tuple[float, list[dict]]] = {}


def leagues_for(sport: Optional[str]) -> list[str]:
    text = (sport or "").lower()
    if re.search(NO_FREE_LOOKUP, text):
        return []
    found = [path for pattern, path, _ in LEAGUES if re.search(pattern, text)]
    return found or DEFAULT_LEAGUES


HTTP_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) "
           "Chrome/126.0.0.0 Safari/537.36")
HTTP_RETRIES = 2              # extra tries after the first, on 429 / 5xx / timeouts / dropped connections
HTTP_HOST_LIMIT = 6           # requests in flight per host
_HTTP: dict = {"session": None, "loop": None, "sems": {}}
DATA_HEALTH: dict[str, dict] = {}   # host -> {ok, fail, streak, status, last_ok, last_fail, fail_since}


class HttpStatusError(Exception):
    """A non-2xx answer. `status` is the HTTP code; `retry_after` is the server's hint in seconds (429/503)."""

    def __init__(self, status: int, url: str, retry_after: Optional[float] = None):
        super().__init__(f"HTTP {status} for {url.split('?')[0]}")
        self.status, self.retry_after = status, retry_after


async def _get_json(url: str, params: dict) -> dict:
    """GET a JSON document. Every free-data call (ESPN, Kalshi, trivia) goes through here; tests swap it out."""
    return await _http_get_json(url, params)


def _http_session():
    """The shared aiohttp session, made on first use and again if it was closed or the event loop changed."""
    loop = asyncio.get_running_loop()
    sess = _HTTP["session"]
    if sess is None or getattr(sess, "closed", False) or _HTTP["loop"] is not loop:
        import aiohttp  # comes with discord.py
        sess = aiohttp.ClientSession(
            timeout=aiohttp.ClientTimeout(total=12, connect=5, sock_read=10),
            headers={"User-Agent": HTTP_UA, "Accept": "application/json, text/plain, */*",
                     "Accept-Language": "en-US,en;q=0.9"},
            connector=aiohttp.TCPConnector(limit=40, ttl_dns_cache=300))
        _HTTP.update(session=sess, loop=loop, sems={})
    return sess


def _http_sem(host: str) -> asyncio.Semaphore:
    if _HTTP["loop"] is not asyncio.get_running_loop():
        _HTTP.update(loop=None, sems={})
    sem = _HTTP["sems"].get(host)
    if sem is None:
        sem = _HTTP["sems"][host] = asyncio.Semaphore(HTTP_HOST_LIMIT)
    return sem


def _health_note(host: str, ok: bool, status) -> None:
    """Count one finished call. `ok` means the host answered (a 404 is an answer); failures are 5xx, 429,
    timeouts and dropped connections."""
    h = DATA_HEALTH.setdefault(host, {"ok": 0, "fail": 0, "streak": 0, "status": None, "last_ok": None,
                                      "last_fail": None, "fail_since": None})
    now = time.time()
    h["status"] = status
    if ok:
        h.update(ok=h["ok"] + 1, streak=0, last_ok=now, fail_since=None, alerted=False)
    else:
        h.update(fail=h["fail"] + 1, streak=h["streak"] + 1, last_fail=now, fail_since=h["fail_since"] or now)
        if h["streak"] == 3 and not h.get("alerted"):
            h["alerted"] = True
            name = host
            try:
                name = HEALTH_NAMES.get(host) or DASH30_HOSTS.get(host) or host
            except Exception:
                pass
            why = f"{h['fail']} failed calls in a row"
            if status:
                why += f" (last http {status})"
            try:
                asyncio.get_running_loop().create_task(
                    crash_notify(bot, "feed", f"{name} is down", why))
            except Exception:
                crash_note("feed", f"{name} is down", why)


def _http_retryable(exc: Exception) -> bool:
    if isinstance(exc, HttpStatusError):
        return exc.status == 429 or exc.status >= 500
    if isinstance(exc, (asyncio.TimeoutError, OSError)):
        return True
    name = type(exc).__name__
    return any(x in name for x in ("ClientConnector", "ServerDisconnected", "ClientOSError", "ClientPayload",
                                   "ServerTimeout", "ClientConnection"))


async def _http_get_json(url: str, params: dict, session=None) -> dict:
    """The real GET behind _get_json: up to HTTP_RETRIES retries with backoff, HTTP_HOST_LIMIT calls per host at a
    time, and DATA_HEALTH kept per host. Raises HttpStatusError (or the network error) when it gives up."""
    from urllib.parse import urlsplit
    host = urlsplit(url).hostname or "?"
    last: Optional[Exception] = None
    for attempt in range(HTTP_RETRIES + 1):
        if attempt:
            hint = getattr(last, "retry_after", None)
            wait = hint if hint is not None and 0 <= hint <= 5 else 0.6 * 2 ** (attempt - 1)
            await asyncio.sleep(wait + (attempt * 0.137) % 0.3)
        try:
            async with _http_sem(host):
                sess = session or _http_session()
                async with sess.get(url, params=params) as resp:
                    status = resp.status
                    if status >= 400:
                        ra = None
                        try:
                            ra = float((resp.headers or {}).get("Retry-After"))
                        except (TypeError, ValueError):
                            pass
                        raise HttpStatusError(status, url, ra)
                    data = await resp.json(content_type=None)
            _health_note(host, True, status)
            return data
        except Exception as exc:
            last = exc
            if not _http_retryable(exc):
                if isinstance(exc, HttpStatusError):
                    _health_note(host, True, exc.status)     # the host answered; the thing just isn't there
                raise
    _health_note(host, False, getattr(last, "status", type(last).__name__))
    raise last


def simplify_events(raw: dict) -> list[dict]:
    """Keep what grading needs from an ESPN scoreboard response."""
    events = []
    for ev in raw.get("events") or []:
        comp = (ev.get("competitions") or [{}])[0]
        status = (ev.get("status") or comp.get("status") or {}).get("type") or {}
        teams = []
        for c in comp.get("competitors") or []:
            t = c.get("team") or {}
            try:
                score = float(c.get("score")) if c.get("score") not in (None, "") else None
            except (TypeError, ValueError):
                score = None
            teams.append({"id": str(t.get("id") or t.get("displayName")), "score": score,
                          "name": t.get("displayName") or "", "abbr": t.get("abbreviation") or "",
                          "color": t.get("color") or "", "alt_color": t.get("alternateColor") or "",
                          "logo": t.get("logo") or ((t.get("logos") or [{}])[0] or {}).get("href") or "",
                          "linescores": [x.get("value") for x in c.get("linescores") or [] if isinstance(x, dict)],
                          "records": {r.get("name") or r.get("type") or "?": r.get("summary") for r in c.get("records") or []
                                      if r.get("summary")},
                          "home": c.get("homeAway") == "home",
                          "short": t.get("shortDisplayName") or t.get("displayName") or "?",
                          "aliases": {norm_team(x) for x in (t.get("displayName"), t.get("shortDisplayName"),
                                      t.get("location"), t.get("abbreviation")) if x},
                          "nickname": norm_team(t.get("name") or "")})
        leaders = []
        for holder in [comp] + list(comp.get("competitors") or []):
            for cat in holder.get("leaders") or []:
                top = (cat.get("leaders") or [{}])[0]
                ath = top.get("athlete") or {}
                if ath.get("id") and ath.get("displayName"):
                    leaders.append({"category": cat.get("name") or "", "athlete_id": str(ath["id"]),
                                    "name": ath["displayName"]})
        if len(teams) == 2:
            venue = comp.get("venue") or {}
            events.append({"period": (ev.get("status") or comp.get("status") or {}).get("period") or 0,
                           "leaders": leaders, "venue": {"name": venue.get("fullName") or "",
                                                         "city": (venue.get("address") or {}).get("city") or "",
                                                         "state": (venue.get("address") or {}).get("state") or "",
                                                         "indoor": bool(venue.get("indoor"))}, "id": str(ev.get("id")), "date": ev.get("date") or "", "teams": teams,
                           "state": status.get("state") or "pre", "status_name": status.get("name") or "",
                           "final": bool(status.get("completed")) and status.get("state") == "post",
                           "week": (ev.get("week") or {}).get("number"),
                           "detail": status.get("shortDetail") or "",
                           "season_type": (ev.get("season") or {}).get("type"),
                           "season": (ev.get("season") or {}).get("year")})
    return events


async def fetch_scoreboard(path: str, day: datetime, params: Optional[dict] = None) -> list[dict]:
    extra = params if params is not None else next((x for _, pth, x in LEAGUES if pth == path), {})
    key = (path, day.strftime("%Y%m%d"), tuple(sorted(extra.items())))
    hit = _score_cache.get(key)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    try:
        raw = await _get_json(ESPN.format(path=path), {"dates": key[1], **extra})
        events = simplify_events(raw)
        ttl = scoreboard_ttl(events)
    except Exception:
        log.warning("Scoreboard lookup failed for %s %s", path, key[1])
        events, ttl = [], 180
    _score_cache[key] = (time.monotonic() + ttl, events)
    return events


def scoreboard_ttl(events: list[dict], now: Optional[datetime] = None) -> int:
    """Seconds to keep a day's scoreboard: 1 minute while a game is on, 2 when one starts within 2 hours (or
    should have started), 15 minutes when everything left is later than that, 6 hours once everything is final,
    10 minutes for a day with no games (a game added late, or a feed that answered empty)."""
    now = now or datetime.now(timezone.utc)
    if not events:
        return 600
    if any(e.get("state") == "in" for e in events):
        return 60
    pending = [e for e in events if not e.get("final")]
    if not pending:
        return 6 * 3600
    starts = [event_time(e) for e in pending]
    if any(t is None or t <= now + timedelta(hours=2) for t in starts):
        return 120          # starting soon, or should have started (ESPN can lag a few minutes)
    return 900


def norm_team(text: str) -> str:
    t = re.sub(r"[.'’]", "", (text or "").lower())
    t = re.sub(r"\bst\b", "state", t)
    t = re.sub(r"^the ", "", t)
    return " ".join(t.split())


def team_matches(text: str, team: dict) -> bool:
    """Bio name, abbreviation, short name, and nickname all count as the club."""
    n = norm_team(text)
    if not n or not isinstance(team, dict):
        return False
    aliases = team.get("aliases") or set()
    nick = team.get("nickname") or ""
    if n in aliases or (nick and n == nick):
        return True
    if any(n == norm_team(str(team.get(k) or "")) for k in ("abbr", "short", "name")):
        return True
    return bool(nick) and n.endswith(" " + nick)  # "KC Chiefs", "LA Rams"


def parse_simple_leg(text: str) -> Optional[dict]:
    """Moneyline, spread, game total or team total, or None if it's anything else."""
    t = text.strip()
    negate = False
    m = re.search(r"\((yes|no)\b[^)]*\)\s*$", t, re.I)       # Kalshi "(NO @ 20¢)"
    if m:
        negate = m.group(1).lower() == "no"
    m = re.match(r"^\s*(no|yes)\s*[-–:,]\s*(.+)$", t, re.I)   # "No - Penn St. wins by over 48.5"
    if m:
        negate ^= m.group(1).lower() == "no"
        t = m.group(2)
    t = re.sub(r"\s*\([^)]*\)", "", t)                          # drop "(vs Clemson)" and similar
    t = re.sub(r"\s*\([^)]*$", "", t).strip()                    # and a cut-off "(vs B..."
    if ": " in t:
        t = t.rsplit(": ", 1)[1]                                   # "IND Colts at KC Chiefs: Will KC Chiefs win?"
    t = t.rstrip("?! ").strip()
    if NOT_SIMPLE.search(t):
        return None
    num = r"(\d+(?:\.\d+)?)"
    unit = r"(?:\s+(?:total\s+)?(?:points|pts|runs|goals)(?:\s+scored)?)?"
    patterns = [
        (rf"^will (?:the )?(.+?) win$", "ml"),
        (rf"^(.+?) wins? by (?:over|more than) {num}{unit}$", "margin"),
        (rf"^(.+?)\s+([+-]{num[1:-1]})(?:\s+spread)?$", "spread"),
        (r"^(.+?)\s+(?:ml|moneyline|to win|wins|win)$", "ml"),
        (rf"^(over|under)\s+{num}{unit}$", "total"),
        (rf"^(.+?)\s+(over|under)\s+{num}{unit}$", "team_total"),
    ]
    for pattern, kind in patterns:
        m = re.match(pattern, t, re.I)
        if not m:
            continue
        g = m.groups()
        if kind == "ml":
            return {"kind": kind, "team": g[0], "negate": negate}
        if kind == "spread" and abs(float(g[1])) >= 100:      # "Lakers +150" is a moneyline price, not a spread
            return {"kind": "ml", "team": g[0], "negate": negate}
        if kind in ("margin", "spread"):
            return {"kind": kind, "team": g[0], "line": float(g[1]), "negate": negate}
        if kind == "total":
            return {"kind": kind, "side": g[0].lower(), "line": float(g[1]), "negate": negate}
        return {"kind": kind, "team": g[0], "side": g[1].lower(), "line": float(g[2]), "negate": negate}
    return None


def paren_teams(text: str) -> list[str]:
    out = []
    for inside in re.findall(r"\(([^)]*)\)", text or ""):
        parts = re.split(r"\s+(?:vs\.?|v|at)\s+|\s*[@/]\s*", inside.strip(), flags=re.I)
        if len(parts) == 2 and all(1 < len(x) < 40 for x in parts):
            out += [x.strip() for x in parts]
    return out


async def find_games(team_text: str, leagues: list[str], start: datetime) -> list[tuple[dict, int]]:
    """Games in the days around `start` that this team played: [(event, index of the team)]. Looks from a day
    before to three after, and out to TRACK_DAYS_AHEAD days only when that finds nothing from 18 hours before
    `start` on (a Monday leg on a Thursday slate). A soccer team is the same team in every competition."""
    matches, team_ids = [], set()
    floor = start - timedelta(hours=18)
    for offsets in (range(-1, 4), range(4, TRACK_DAYS_AHEAD + 1)):
        days = [(start + timedelta(days=o)).astimezone(TZ) for o in offsets]
        for path in leagues:
            boards = await asyncio.gather(*(fetch_scoreboard(path, d) for d in days))
            for evs in boards:
                for ev in evs:
                    for i, team in enumerate(ev["teams"]):
                        if team_matches(team_text, team):
                            ev.setdefault("path", path)
                            matches.append((ev, i))
                            team_ids.add(("soccer" if path.startswith("soccer/") else path, team["id"]))
        if any((event_time(ev) or floor) >= floor for ev, _ in matches):
            break
    track_note_miss(team_text, start, "many" if len(team_ids) > 1 else ("none" if not team_ids else ""))
    if len(team_ids) != 1:
        return []  # nobody, or more than one team answers to that name
    seen, unique = set(), []
    for ev, i in sorted(matches, key=lambda m: m[0]["date"]):
        if ev["id"] not in seen:
            seen.add(ev["id"])
            unique.append((ev, i))
    return unique


class SlateAnchor(datetime):
    """A search anchor that came from a slip's slate date rather than from when it was logged."""


def pick_game(games: list[tuple[dict, int]], logged: datetime) -> Optional[tuple[dict, int]]:
    """The first game starting no more than 18 hours before the bet was logged. When the anchor is a slate date
    (a multi-day slip read as Friday that also has Thursday-night legs) and this team has nothing coming up in the
    next 3 days, its game from the day before counts instead."""
    floor = logged - timedelta(hours=18)
    first, earlier = None, []
    for ev, i in games:
        try:
            when = datetime.fromisoformat(ev["date"].replace("Z", "+00:00"))
        except (ValueError, TypeError, AttributeError):
            continue
        if when.tzinfo is None:
            when = when.replace(tzinfo=timezone.utc)
        if when >= floor:
            first = (ev, i)
            break
        if when >= logged - timedelta(hours=42) and ev.get("state") in ("in", "post"):
            earlier.append((ev, i))
    if isinstance(logged, SlateAnchor) and earlier:
        if first is None or event_time(first[0]) is None or event_time(first[0]) > logged + timedelta(hours=72):
            return earlier[-1]
    return first


def score_line(ev: dict) -> str:
    away, home = sorted(ev["teams"], key=lambda t: t["home"])
    return f"{away['short']} {away['score']:g}, {home['short']} {home['score']:g} (final)"


def judge(leg: dict, ev: dict, i: Optional[int]) -> Optional[str]:
    if i is not None:
        mine, theirs = ev["teams"][i]["score"], ev["teams"][1 - i]["score"]
    total = sum(t["score"] for t in ev["teams"])
    kind = leg["kind"]
    if kind == "ml":
        result = None if mine == theirs else ("hit" if mine > theirs else "miss")
    elif kind == "spread":
        v = mine - theirs + leg["line"]
        result = "push" if v == 0 else ("hit" if v > 0 else "miss")
    elif kind == "margin":
        result = "hit" if mine - theirs > leg["line"] else "miss"
    else:
        value = total if kind == "total" else mine
        if value == leg["line"]:
            result = "push"
        else:
            result = "hit" if (value > leg["line"]) == (leg["side"] == "over") else "miss"
    if result and leg["negate"] and result != "push":
        result = "miss" if result == "hit" else "hit"
    return result


async def free_grade(p, items: list[tuple[int, str]],
                     context_legs: Optional[list[str]] = None) -> dict[int, tuple[str, str]]:
    """Grade what the public scoreboard can settle. Returns {item number: (result, why)};
    items it can't settle are left out."""
    leagues = leagues_for(p["sport"])
    logged = pick_anchor(p)
    parsed = {n: (parse_simple_leg(text) if leagues else None) for n, text in items}
    # Teams named anywhere on the pick, so a bare "Over 44.5" can find its game.
    context_teams = [x["team"] for x in parsed.values() if x and "team" in x]
    for leg_text in (context_legs if context_legs is not None else [leg["text"] for leg in get_legs(p["id"])]):
        x = parse_simple_leg(leg_text)
        if x and "team" in x:
            context_teams.append(x["team"])
    for _, text in items:   # "Over 44.5 (Bills vs Dolphins)"
        context_teams += paren_teams(text)
    out: dict[int, tuple[str, str]] = {}
    for n, leg in parsed.items():
        if not leg:
            continue
        if leg["kind"] == "total":
            games = {}
            for team in set(context_teams):
                found = pick_game(await find_games(team, leagues, logged), logged)
                if found:
                    games[found[0]["id"]] = found
            if len(games) != 1:
                continue
            ev, i = next(iter(games.values()))
            i = None
        else:
            found = pick_game(await find_games(leg["team"], leagues, logged), logged)
            if not found:
                continue
            ev, i = found
        if ev.get("season_type") == 1 and p["id"] and p["id"] > 0:
            mark_preseason(p["id"])
        if not ev["final"] or any(t["score"] is None for t in ev["teams"]):
            continue
        result = judge(leg, ev, i)
        if result:
            out[n] = (result, score_line(ev))
            mg = simple_margin(leg, ev, i)
            if mg is not None and p["id"]:
                _margins[(p["id"], n)] = mg
    out.update(await grade_props(p, items, set(out)))
    return out


GRADE_SYSTEM = """You grade sports bets for a group of friends. Search the web for final \
results and box scores, then decide each item.

- hit: the bettor's side won. miss: it lost. push: landed exactly on the line, or was \
voided or cancelled (player didn't play, game called off).
- unknown: the event isn't final yet, or you can't find the stat. Never guess. A wrong \
grade costs someone money on the scoreboard; unknown just means a person settles it.
- Prediction markets (Kalshi): "(NO @ 20¢)" means the bettor wins if the question \
resolves No; "(YES ...)" means it wins on Yes. A leg written as "No - <statement>" wins \
when the statement is false.
- Player props: "15+ receiving yards" means 15 or more. "over 249.5" means 250 or more.

Reply with ONLY a JSON object, no other text:
{"items": [{"n": 1, "result": "hit" | "miss" | "push" | "unknown", "why": "under 12 words, with the stat or score"}]}"""


def grade_request(p: sqlite3.Row, items: list[tuple[int, str]], single: bool) -> str:
    logged = datetime.fromisoformat(p["created_at"]).astimezone(TZ).strftime("%A, %B %d, %Y")
    lines = [f"Today is {datetime.now(TZ).strftime('%A, %B %d, %Y')}.",
             f"Bet logged {logged} on {p['platform']}" + (f" ({p['sport']})" if p["sport"] else "") + ".",
             f"The bet: {p['description']}"]
    if _rg(p, "slate_date"):
        lines.append(f"The games on this slip were on or after {_rg(p, 'slate_date')} (local date).")
    if p["notes"]:
        lines.append(f"Bettor's notes: {clip(p['notes'], 400)}")
    if single:
        lines.append("It has no separate legs, so grade the bet itself as item 1.")
    lines.append("Items to grade:")
    lines += [f"{n}. {text}" for n, text in items]
    return "\n".join(lines)


async def lookup_items(p, items: list[tuple[int, str]], single: bool, allow_ai: bool,
                       context_legs: Optional[list[str]] = None) -> tuple[dict[int, dict], bool]:
    """Free scoreboard first, then Claude for the rest. Returns ({n: {result, why}}, used Claude)."""
    by_n: dict[int, dict] = {}
    try:
        for n, (result, why) in (await free_grade(p, items, context_legs)).items():
            by_n[n] = {"result": result, "why": why}
    except Exception:
        log.exception("Free lookup failed")
    rest = [(n, t) for n, t in items if n not in by_n]
    used_ai = False
    if rest and allow_ai and ai_enabled():
        used_ai = True
        text, _ = await ask_claude(GRADE_SYSTEM, grade_request(p, rest, single),
                                   max_searches=min(3 + len(rest), 10))
        for r in extract_json(text).get("items") or []:
            try:
                n = int(r.get("n"))
            except (TypeError, ValueError):
                continue
            if n in dict(rest):
                by_n[n] = r
    return by_n, used_ai


async def autograde(guild_id: int, pick_id: int,
                    allow_ai: bool = True) -> tuple[Optional[sqlite3.Row], list[str], bool, bool]:
    """Look up results for a pick's open legs and apply them: the free scoreboard first,
    then Claude (if allowed) for whatever's left.
    Returns (pick, one line per item, whether anything was graded, whether Claude was used)."""
    p = get_pick(guild_id, pick_id)
    legs = get_legs(pick_id)
    single = not legs
    items = [(1, p["description"])] if single else [(leg["idx"], leg["text"]) for leg in legs
                                                    if leg["status"] == "open"]
    tries = (p["autograde_tries"] or 0) + 1
    db().execute("UPDATE picks SET autograde_at = ?, autograde_tries = ? WHERE id = ?",
                 (now_iso(), tries, pick_id))
    db().commit()
    if not items:
        return p, [], False, False
    by_n, used_ai = await lookup_items(p, items, single, allow_ai)
    lines, graded = apply_results(guild_id, pick_id, items, by_n, single)
    return get_pick(guild_id, pick_id), lines, graded, used_ai


def grading_message(p: sqlite3.Row, lines: list[str], final_try: bool) -> str:
    head = f"🤖 Looked up results for pick `#{p['id']}` ({p['bettor_name']}): {clip(p['description'], 80)}"
    body = "\n".join(lines)
    if p["status"] != "open":
        net = (p["returned"] or 0.0) - p["cost"]
        tail = (f"Result: **{STATUS[p['status']][0]}** ({signed(net)}). Wrong, or cashed out early? "
                f"Fix it with `/leg` or `/result pick_id:{p['id']}`.")
        if _rg(p, "estimated"):
            tail += (f"\n-# {money(p['returned'] or 0)} back is an estimate from the payout table (a leg pushed or a "
                     "Flex partly hit). If the app paid something else, use `/result` with the real amount.")
    elif final_try:
        tail = f"I couldn't settle this one. Settle it with `/result pick_id:{p['id']}`."
    elif p["platform"].lower() == "prizepicks" and any(leg["status"] == "miss" for leg in get_legs(p["id"])):
        tail = f"Flex entries can still pay, so settle it with `/result pick_id:{p['id']}` and the amount returned."
    else:
        tail = "Still open. I'll look again in 12 hours."
    return f"{head}\n{body}\n{tail}"


