WEB_PORT = env("PORT", "")
PUBLIC_DOMAIN = env("RAILWAY_PUBLIC_DOMAIN", "")


def dashboard_key() -> str:
    """Stable cookie secret. Never shown. Env DASHBOARD_KEY still works as a master sign-in."""
    key = env("DASHBOARD_KEY", "")
    if key:
        return key
    key = get_setting(0, "dashboard_key")
    if not key:
        key = secrets.token_urlsafe(18)
        set_setting(0, "dashboard_key", key)
    return key


DASH_ANSWERED: dict = {"at": None}


def dashboard_url() -> Optional[str]:
    if not PUBLIC_DOMAIN:
        return None
    return f"https://{PUBLIC_DOMAIN}/"


def _dash_key_match(a: Optional[str], b: str) -> bool:
    if not a or not b or len(a) > 128:
        return False
    ae, be = a.encode(), b.encode()
    if len(ae) != len(be):
        hmac.compare_digest(ae, ae)
        return False
    return hmac.compare_digest(ae, be)


def dash_gate_state() -> dict:
    """Today's unused access code. Minted at midnight and again each time someone signs in with it."""
    day = datetime.now(TZ).date().isoformat()
    try:
        d = json.loads(get_setting(0, "dash_gate") or "{}")
    except Exception:
        d = {}
    if not isinstance(d, dict):
        d = {}
    if d.get("day") != day or not d.get("code") or len(str(d.get("code") or "")) > 40:
        d = {"day": day, "code": secrets.token_urlsafe(10), "used": int(d.get("used") or 0)}
        set_setting(0, "dash_gate", json.dumps(d))
    return d


def dash_gate_code() -> str:
    return str(dash_gate_state().get("code") or "")


def dash_gate_rotate() -> str:
    day = datetime.now(TZ).date().isoformat()
    prev = dash_gate_state()
    d = {"day": day, "code": secrets.token_urlsafe(10), "used": int(prev.get("used") or 0) + 1}
    set_setting(0, "dash_gate", json.dumps(d))
    return d["code"]


def dash_take_key(candidate: Optional[str]) -> bool:
    """True when this key may sign in. A one-time staff code is spent and a fresh one is minted."""
    if _dash_key_match(candidate, dashboard_key()):
        return True
    if _dash_key_match(candidate, dash_gate_code()):
        dash_gate_rotate()
        return True
    return False


def dash_this_week(guild_id: int) -> dict:
    """Open slips, plus what settled since Monday: count, net, and coins earned."""
    now = datetime.now(TZ)
    start = (now - timedelta(days=now.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
    settled, net = 0, 0.0
    try:
        rows = db().execute(
            """SELECT cost, returned, settled_at, created_at, hidden, revealed_at, test FROM picks
               WHERE guild_id = ? AND status != 'open'""", (guild_id,)).fetchall()
    except Exception:
        rows = []
    for p in rows:
        if p["hidden"] and not p["revealed_at"]:
            continue
        if p["test"]:
            continue
        raw = p["settled_at"] or p["created_at"] or ""
        try:
            when = datetime.fromisoformat(raw)
        except Exception:
            continue
        if when.tzinfo is None:
            when = when.replace(tzinfo=timezone.utc)
        if when.astimezone(TZ) < start:
            continue
        settled += 1
        net += (p["returned"] or 0.0) - (p["cost"] or 0.0)
    try:
        open_n = db().execute(
            """SELECT COUNT(*) AS n FROM picks WHERE guild_id = ? AND status = 'open'
               AND (hidden IS NULL OR hidden = 0) AND (test IS NULL OR test = 0)""", (guild_id,)).fetchone()["n"]
    except Exception:
        open_n = 0
    coins = 0
    try:
        for tx in db().execute("SELECT delta, created_at FROM coin_tx WHERE guild_id = ?", (guild_id,)):
            try:
                when = datetime.fromisoformat(tx["created_at"])
            except Exception:
                continue
            if when.tzinfo is None:
                when = when.replace(tzinfo=timezone.utc)
            if when.astimezone(TZ) >= start and int(tx["delta"] or 0) > 0:
                coins += int(tx["delta"])
    except Exception:
        coins = 0
    return {"open": int(open_n or 0), "settled": settled, "net": round(net, 2), "coins": coins}


def dash_week_plays(guild_id: int) -> list[dict]:
    """Slips logged since Monday, for the small board of what the crew put in this week."""
    now = datetime.now(TZ)
    start = (now - timedelta(days=now.weekday())).strftime("%Y-%m-%d")
    out = []
    try:
        rows = db().execute(
            """SELECT * FROM picks WHERE guild_id = ? ORDER BY id DESC LIMIT 40""", (guild_id,)).fetchall()
    except Exception:
        return []
    for p in rows:
        if p["hidden"] and not p["revealed_at"]:
            continue
        if pick_is_test(p):
            continue
        if local_stamp(p["created_at"] or "") < start:
            continue
        uid = p["bettor_id"]
        key = str(uid) if uid and str(uid).isdigit() else (p["bettor_key"] if str(p["bettor_key"] or "").isdigit() else "")
        net = None if p["status"] == "open" else round(pick_net(p), 2)
        out.append({"id": p["id"], "who": clip(p["bettor_name"], 40), "key": key,
                    "what": clip(p["description"] or "", 80), "net": net, "status": p["status"] or "open"})
        if len(out) >= 12:
            break
    return out


def dash_prop_name(text: str) -> str:
    """Player display name when this line is a player prop. Empty for parlays, totals, and team bets."""
    try:
        pr = parse_prop_leg(text or "")
    except Exception:
        pr = None
    if not isinstance(pr, dict) or pr.get("kind") != "prop" or pr.get("combo"):
        return ""
    return clip(str(pr.get("display") or ""), 40)


def dash_commands() -> list:
    """The same groups /help uses, so More can list every command on one page."""
    try:
        fields = help_embed().fields
    except Exception:
        return []
    return [{"name": clip(f.name, 48), "text": f.value} for f in fields]


def dashboard_data(guild_id: int) -> dict:
    season = current_season(guild_id)
    def board(stats):
        return [{"key": s["key"], "name": s["name"], "record": record_line(s), "net": round(s["net"], 2),
                 "roi": round(s["roi"], 1), "streak": current_streak(guild_id, s["key"]), "open": s["open"]}
                for s in stats if s["wins"] + s["losses"] + s["pushes"] > 0]
    series = chart_series(guild_id, 3650)
    recent = [{"id": p["id"], "who": p["bettor_name"], "key": str(p["bettor_id"] or ""),
               "what": shown_desc(p), "platform": p["platform"],
               "sport": clip(p["sport"] or "", 24), "status": p["status"], "net": round(pick_net(p), 2),
               "cost": p["cost"], "payout": p["payout"], "when": local_day(p["settled_at"] or p["created_at"]),
               "stamp": local_stamp(p["settled_at"] or p["created_at"] or "")}
              for p in db().execute("""SELECT * FROM picks WHERE guild_id = ? AND status != 'open' AND
                                       (hidden IS NULL OR hidden = 0 OR revealed_at IS NOT NULL)
                                       AND (test IS NULL OR test = 0)
                                       ORDER BY settled_at DESC LIMIT 25""", (guild_id,))]
    open_ = [{"id": p["id"], "who": p["bettor_name"], "key": str(p["bettor_id"] or ""),
              "what": shown_desc(p), "platform": p["platform"],
              "sport": clip(p["sport"] or "", 24), "cost": p["cost"], "payout": p["payout"],
              "slate": local_day(p["slate_date"]) if _rg(p, "slate_date") else "",
              "player": dash_prop_name(shown_desc(p)) or None}
             for p in db().execute("""SELECT * FROM picks WHERE guild_id = ? AND status = 'open'
                                       AND (hidden IS NULL OR hidden = 0)
                                       AND (future_due IS NULL OR future_due = '')
                                       AND (test IS NULL OR test = 0)
                                       ORDER BY id DESC LIMIT 40""", (guild_id,))]
    futures = [{"id": p["id"], "who": clip(p["bettor_name"], 40), "what": clip(shown_desc(p), 90),
                "due": local_day(p["future_due"]) if p["future_due"] else "",
                "cost": p["cost"], "payout": p["payout"]}
               for p in db().execute("""SELECT * FROM picks WHERE guild_id = ? AND status = 'open'
                                        AND (hidden IS NULL OR hidden = 0)
                                        AND future_due IS NOT NULL AND future_due != ''
                                        AND (test IS NULL OR test = 0)
                                        ORDER BY future_due LIMIT 20""", (guild_id,))]
    r = gp_round(guild_id, create=False)
    gp = [{"who": x["user_name"], "leg": x["text"], "status": x["status"]} for x in gp_legs(r["id"])] if r else []
    names = {}
    for p in db().execute("SELECT bettor_id, bettor_name FROM picks WHERE guild_id = ? AND bettor_id IS NOT NULL", (guild_id,)):
        names[p["bettor_id"]] = p["bettor_name"]
    coins = []
    for u in coins_top(guild_id, 10):
        why = ""
        try:
            last = db().execute(
                "SELECT reason FROM coin_tx WHERE guild_id = ? AND user_id = ? ORDER BY id DESC LIMIT 1",
                (guild_id, u["user_id"])).fetchone()
            why = clip(last["reason"], 48) if last else ""
        except Exception:
            why = ""
        game = ""
        try:
            lastp = db().execute(
                """SELECT description, sport FROM picks WHERE guild_id = ? AND bettor_id = ? AND status != 'open'
                   ORDER BY settled_at DESC LIMIT 1""", (guild_id, u["user_id"])).fetchone()
            if lastp:
                game = clip(((lastp["sport"] or "") + " " + (lastp["description"] or "")).strip(), 48)
        except Exception:
            game = ""
        coins.append({"who": names.get(u["user_id"], "Member"), "coins": int(u["bal"]), "why": why, "game": game})
    rec = dash30_safe_records(guild_id, records_embed(guild_id).description or "")
    markets = []
    for p in db().execute(
            """SELECT * FROM picks WHERE guild_id = ? AND status = 'open'
               AND (hidden IS NULL OR hidden = 0)
               AND (LOWER(COALESCE(platform,'')) = 'kalshi'
                    OR (kalshi_ticker IS NOT NULL AND kalshi_ticker != ''))
               ORDER BY id DESC LIMIT 12""", (guild_id,)):
        markets.append({"id": p["id"], "who": clip(p["bettor_name"], 40), "what": clip(shown_desc(p), 80),
                        "platform": clip(p["platform"] or "Kalshi", 20),
                        "ticker": clip(p["kalshi_ticker"] or "", 32),
                        "side": clip(p["kalshi_side"] or "", 8)})
    return {"version": BOT_VERSION, "update": ROADMAP_NOW, "season": season["name"] if season else None, "people": dashboard_people(guild_id),
            "settled24": dashboard_recent(guild_id),
            "leaderboard": board(season_stats(guild_id, season) if season else compute_stats(guild_id)),
            "alltime": board(compute_stats(guild_id)),
            "series": {k: [[x.astimezone(TZ).strftime("%Y-%m-%d %H:%M"), round(y, 2)] for x, y in v] for k, v in series.items()},
            "recent": recent, "open": open_, "futures": futures, "tickets": list(open_[:12]), "markets": markets,
            "commands": dash_commands(),
            "groupparlay": gp, "coins": coins,
            "records": [re.sub(r"\*\*", "", line) for line in rec.split("\n") if line],
            "records": [re.sub(r"\*\*", "", line) for line in rec.split("\n") if line],
            "roadmap": BOT_ROADMAP, "plan": BOT_PLAN, "later": BOT_LATER, "thousand": BOT_THOUSAND,
            "updates": [{"ver": v, "text": t} for v, t in reversed(MEMBER_NEWS[-5:])],
            "week": dash_this_week(guild_id),
            "netmode": "group" if get_setting(guild_id, "kpi_net") == "group" else "week",
            "groupnet": round(sum(s["net"] for s in compute_stats(guild_id)), 2),
            "h2h": dash_h2h_board(guild_id), "weekplays": dash_week_plays(guild_id),
            "weekboard": clip(get_setting(guild_id, "week_board") or "", 280)}


