def _city_words(text: str) -> str:
    raw = re.sub(r"[.'’]", "", (text or "").lower())
    raw = " ".join(raw.split())
    drop = {w.lower() for w in US_STATES} | {w.lower() for w in US_STATES.values()}
    drop |= {"city", "metro", "area", "downtown"}
    kept = [w for w in raw.split() if w not in drop]
    return " ".join(kept) or raw


def weather_city_key(phrase: Optional[str]) -> Optional[str]:
    """Club-city key for a typed place, including 'san fransico' and 'sf'. None when it is not one of those cities."""
    raw = _city_words(phrase or "")
    if not raw:
        return None
    if raw in _CITY_ALIAS:
        raw = _CITY_ALIAS[raw]
    if raw in CITY_CLUBS:
        return raw
    padded = f" {raw} "
    contained = [key for key in CITY_CLUBS if f" {key} " in padded]
    if contained:
        return max(contained, key=len)
    if len(raw) < 5:
        return None
    best, score = None, 0.0
    for key in CITY_CLUBS:
        s = _name_ratio(raw, key)
        if s > score:
            best, score = key, s
    return best if best and score >= 0.9 else None


def weather_place_query(phrase: Optional[str]) -> str:
    """Geocoder string. A nickname or a close misspelling becomes the real city. Anything else is cleaned and kept."""
    key = weather_city_key(phrase)
    if key:
        return " ".join(w.capitalize() for w in key.split())
    return " ".join((phrase or "").split())


def _place_close(query: str, result: dict) -> bool:
    words = [w for w in re.findall(r"[a-z0-9]+", (query or "").lower()) if len(w) >= 2]
    name = (result.get("name") or "").lower()
    blob = f"{name} {result.get('admin1') or ''}".lower()
    if words and any(w in blob for w in words):
        return True
    q = " ".join((query or "").lower().split())
    if q and _name_ratio(q, name) >= 0.82:
        return True
    nwords = re.findall(r"[a-z0-9]+", name)
    for w in words:
        if len(w) < 5:
            continue
        if any(_name_ratio(w, nw) >= 0.84 for nw in nwords):
            return True
    return False


def _hour_label(stamp: str) -> str:
    hour = int(stamp[11:13])
    return f"{hour % 12 or 12}{'a' if hour < 12 else 'p'}"


def _hour_num(row: dict, key: str, default: float = 0.0) -> float:
    val = row.get(key)
    return float(val) if isinstance(val, (int, float)) else default


def weather_code_word(code) -> str:
    """Plain condition from an Open-Meteo weather code. Empty when the code is missing."""
    try:
        c = int(code)
    except (TypeError, ValueError):
        return ""
    if c == 0:
        return "Clear"
    if c == 1:
        return "Mostly clear"
    if c == 2:
        return "Partly cloudy"
    if c == 3:
        return "Overcast"
    if c in (45, 48):
        return "Fog"
    if c in (51, 53, 55, 56, 57):
        return "Drizzle"
    if c in (61, 63, 65, 66, 67, 80, 81, 82):
        return "Rain"
    if c in (71, 73, 75, 77, 85, 86):
        return "Snow"
    if c in (95, 96, 99):
        return "Thunderstorm"
    return ""


def _place_rank(query: str, result: dict) -> float:
    name = (result.get("name") or "").lower()
    q = " ".join((query or "").lower().split())
    score = _name_ratio(q, name) if q and name else 0.0
    if q and (q in name or name in q):
        score += 0.35
    if (result.get("country_code") or "") == "US" and weather_city_key(query):
        score += 0.08
    pop = result.get("population") or 0
    try:
        score += min(float(pop), 5_000_000) / 5_000_000 * 0.04
    except (TypeError, ValueError):
        pass
    return score


async def place_forecast(name: str, start: datetime) -> Optional[dict]:
    """24 hourly points from Open-Meteo, in the bot's timezone. None when the place or the hours are thin."""
    query = weather_place_query(name) or name
    geo = await cached_json(GEOCODE, {"name": query, "count": 5, "language": "en"}, 86400 * 7)
    results = [r for r in (geo.get("results") or []) if _place_close(query, r) or _place_close(name, r)]
    if not results and query != name:
        geo = await cached_json(GEOCODE, {"name": name, "count": 5, "language": "en"}, 86400 * 7)
        results = [r for r in (geo.get("results") or []) if _place_close(query, r) or _place_close(name, r)]
    if not results:
        return None
    hit = max(results, key=lambda r: _place_rank(query, r))
    lat, lon = hit["latitude"], hit["longitude"]
    label = hit.get("name") or query
    admin = hit.get("admin1")
    place = f"{label}, {admin}" if admin else label
    tzname = getattr(TZ, "key", None) or "America/Chicago"
    day0 = start.astimezone(TZ).date()
    fc = await cached_json(FORECAST, {
        "latitude": lat, "longitude": lon, "timezone": tzname,
        "start_date": day0.isoformat(), "end_date": (day0 + timedelta(days=1)).isoformat(),
        "temperature_unit": "fahrenheit", "wind_speed_unit": "mph",
        "hourly": ("temperature_2m,apparent_temperature,precipitation_probability,precipitation,"
                   "wind_speed_10m,wind_gusts_10m,relative_humidity_2m,weather_code"),
    }, 1800)
    hourly = fc.get("hourly") or {}
    times = hourly.get("time") or []
    temps = hourly.get("temperature_2m") or []
    feels = hourly.get("apparent_temperature") or []
    rains = hourly.get("precipitation_probability") or []
    precips = hourly.get("precipitation") or []
    winds = hourly.get("wind_speed_10m") or []
    gusts = hourly.get("wind_gusts_10m") or []
    hums = hourly.get("relative_humidity_2m") or []
    codes = hourly.get("weather_code") or []
    stamp = start.astimezone(TZ).strftime("%Y-%m-%dT%H:00")
    later = [i for i, t in enumerate(times) if t >= stamp]
    if not later:
        return None

    def at(seq, i):
        return float(seq[i]) if i < len(seq) and isinstance(seq[i], (int, float)) else None

    hours = []
    for i in range(later[0], min(later[0] + 24, len(times))):
        if i >= len(temps) or temps[i] is None:
            continue
        hours.append({
            "label": _hour_label(times[i]),
            "stamp": times[i],
            "temp": float(temps[i]),
            "feel": at(feels, i) if at(feels, i) is not None else float(temps[i]),
            "rain": at(rains, i) or 0.0,
            "precip": at(precips, i) or 0.0,
            "wind": at(winds, i) or 0.0,
            "gust": at(gusts, i) or 0.0,
            "humidity": at(hums, i),
            "code": int(codes[i]) if i < len(codes) and isinstance(codes[i], (int, float)) else None,
        })
    if len(hours) < 4:
        return None
    return {"place": place, "matched": label, "hours": hours, "game": None, "note": None, "games": []}


def weather_story(hours: list, live: bool = True) -> str:
    """One plain readout: condition, feels-like, the warm and cool hours, rain, wind, humidity."""
    if not hours:
        return ""
    temps = [h["temp"] for h in hours]
    feels = [_hour_num(h, "feel", h["temp"]) for h in hours]
    rains = [_hour_num(h, "rain") for h in hours]
    winds = [_hour_num(h, "wind") for h in hours]
    gusts = [_hour_num(h, "gust") for h in hours]
    hi, lo = temps.index(max(temps)), temps.index(min(temps))
    peak = rains.index(max(rains))
    cond = weather_code_word(hours[0].get("code"))
    lead = f"{cond}, " if cond else ""
    opener = "now" if live else f"at {hours[0].get('label') or 'the start'}"
    bits = [f"{lead}{temps[0]:.0f}°F {opener} and it feels like {feels[0]:.0f}°."]
    bits.append(f"Warmest {max(temps):.0f}° around {hours[hi].get('label')}, coolest {min(temps):.0f}° around {hours[lo].get('label')}.")
    if rains[peak] >= 20:
        bits.append(f"Rain chance reaches {rains[peak]:.0f}% around {hours[peak].get('label')}.")
    else:
        bits.append(f"Rain stays low, topping out at {rains[peak]:.0f}% around {hours[peak].get('label')}.")
    gust = max(gusts) if gusts else 0
    if gust >= winds[0] + 8:
        bits.append(f"Wind {winds[0]:.0f} mph {opener}, gusts up to {gust:.0f} mph.")
    else:
        bits.append(f"Wind {winds[0]:.0f} mph {opener}.")
    hum = hours[0].get("humidity")
    if isinstance(hum, (int, float)):
        bits.append(f"Humidity {hum:.0f}%.")
    wet = sum(_hour_num(h, "precip") for h in hours)
    if wet >= 0.05:
        bits.append(f"About {wet:.2f} in of precipitation across these hours.")
    return " ".join(bits)


def weather_brief(pack: dict) -> str:
    hours = pack.get("hours") or []
    bits = []
    place = str(pack.get("place") or "")
    if place:
        bits.append(place + ".")
    story = weather_story(hours, bool(pack.get("live", True)))
    if story:
        bits.append(story)
    rows = [str(g) for g in (pack.get("games") or []) if g]
    if rows:
        bits.append("Coming up: " + " | ".join(rows[:4]) + ".")
    elif pack.get("game"):
        bits.append(str(pack["game"]) + ".")
    if pack.get("note"):
        bits.append(str(pack["note"]))
    return " ".join(b for b in bits if b)


def _chart_start(now: datetime, when: Optional[datetime]) -> datetime:
    """Start the hourly picture so a later kickoff still sits on the graph."""
    if when is None:
        return now
    gw = when.astimezone(TZ)
    if gw <= now + timedelta(hours=20):
        return now
    return gw - timedelta(hours=8)


def _same_city(asked: str, city: str) -> bool:
    a = _city_words(asked)
    b = _city_words(city)
    if not a or not b:
        return False
    if a in b or b in a:
        return True
    return _name_ratio(a, b) >= 0.84


def _game_info(path: str, ev: dict, index: int) -> Optional[dict]:
    venue = ev.get("venue") or {}
    teams = ev.get("teams") or []
    if index < 0 or index >= len(teams):
        return None
    me = teams[index]
    return {
        "game": short_game(ev),
        "when": event_time(ev),
        "city": venue.get("city") or "",
        "state": venue.get("state") or "",
        "indoor": bool(venue.get("indoor")),
        "venue": venue.get("name") or "",
        "team": me.get("short") or me.get("name") or "",
        "path": path,
    }


async def _club_game(path: str, team: str) -> Optional[dict]:
    try:
        found = await next_game(team, [path])
    except Exception:
        log.warning("Weather club lookup failed for %s", team)
        return None
    if not found:
        return None
    got_path, ev, index = found
    if ev.get("final"):
        return None
    return _game_info(got_path, ev, index)


async def city_upcoming(city_key: str) -> list[dict]:
    """Next game for each club tied to this city, soonest first. Away games keep the venue city."""
    clubs = list(CITY_CLUBS.get(city_key) or [])[:4]
    if not clubs:
        return []
    found = await asyncio.gather(*(_club_game(path, team) for path, team in clubs), return_exceptions=True)
    games = [g for g in found if isinstance(g, dict) and g.get("when")]
    now = datetime.now(timezone.utc)
    soon = [g for g in games if g["when"] <= now + timedelta(days=10)]
    soon.sort(key=lambda g: g["when"])
    return soon[:4]


def _chart_game(games: list[dict]) -> Optional[dict]:
    """The picture follows the next outdoor game. An indoor game is used when that is all that is coming up."""
    outdoor = [g for g in games if g.get("city") and not g.get("indoor")]
    if outdoor:
        return outdoor[0]
    for g in games:
        if g.get("city"):
            return g
    return None


def _venue_note(asked: str, game: dict) -> str:
    city = game.get("city") or ""
    team = game.get("team") or "They"
    bits = []
    if game.get("indoor"):
        where = f" at {game['venue']}" if game.get("venue") else ""
        bits.append(f"Indoors{where}. The numbers are the outdoor forecast for {city or 'that city'}.")
    if city and asked and not _same_city(asked, city):
        bits.append(f"{team} plays in {city}, so this forecast is {city}.")
    return " ".join(bits)


async def _game_rows(games: list[dict]) -> list[str]:
    async def one(g: dict) -> str:
        w = None
        if g.get("city") and g.get("when"):
            try:
                w = await kickoff_weather(g["city"], g.get("state") or "", g["when"])
            except Exception:
                w = None
        place = g.get("city") or ""
        if g.get("state"):
            place = f"{place}, {g['state']}" if place else g["state"]
        indoor = "indoors" if g.get("indoor") else ""
        wx = weather_line(w) if w else ""
        return " · ".join(x for x in (g.get("game"), place, indoor, wx) if x)

    rows = await asyncio.gather(*(one(g) for g in games[:4]), return_exceptions=True)
    return [r for r in rows if isinstance(r, str) and r]


async def answer_weather(question: str) -> Optional[dict]:
    """Forecast for a city, or for the city where that city's club is actually playing. Chicago only if no place was named."""
    now = datetime.now(TZ)
    start = now
    if re.search(r"\btomorrow\b", question or "", re.I):
        start = (now + timedelta(days=1)).replace(hour=12, minute=0, second=0, microsecond=0)
    phrase = weather_place_phrase(question)
    query = weather_place_query(phrase) if phrase else ""
    key = weather_city_key(phrase) if phrase else None
    games: list[dict] = []
    if key:
        try:
            games = await asyncio.wait_for(city_upcoming(key), timeout=8)
        except Exception:
            log.warning("Weather games lookup failed for %s", key)
            games = []
    elif phrase:
        try:
            found = await asyncio.wait_for(next_game(phrase, list(LEAGUE_SLUGS)), timeout=5)
        except Exception:
            log.warning("Weather team lookup failed for %s", phrase)
            found = None
        if found:
            info = _game_info(found[0], found[1], found[2])
            if info:
                games = [info]
    focus = _chart_game(games)
    chart_city = (focus.get("city") if focus else None) or query or (phrase or "")
    chart_when = focus.get("when") if focus else None
    chart_start = _chart_start(start, chart_when) if focus else start
    pack = await place_forecast(chart_city, chart_start) if chart_city else None
    if pack is None and query and query != chart_city:
        pack = await place_forecast(query, start)
    if pack is None and phrase and phrase != query and phrase != chart_city:
        pack = await place_forecast(phrase, start)
    if pack is None:
        if phrase:
            return {"place": query or phrase, "matched": "", "hours": [], "game": None, "games": [],
                    "note": None, "brief": f"I couldn't pull a forecast for {query or phrase}.", "now": None, "asked": query or phrase}
        pack = await place_forecast("Chicago", start)
        if pack is None:
            return None
        pack["note"] = "No city was named, so this is Chicago."
    if focus and _same_city(pack.get("matched") or pack.get("place") or "", focus.get("city") or ""):
        pack["game"] = focus.get("game")
        pack["kick"] = focus.get("when")
        note = _venue_note(query or phrase or "", focus)
        if note:
            pack["note"] = note
    elif focus:
        pack["game"] = focus.get("game")
        away = focus.get("city") or "the venue city"
        missed = f"Couldn't pull {away}, so this is {pack.get('place') or 'the forecast'}."
        pack["note"] = f"{pack.get('note') or ''} {missed}".strip()
    elif key:
        quiet = "No upcoming game for a club from this city."
        pack["note"] = f"{pack['note']} {quiet}".strip() if pack.get("note") else quiet
    try:
        pack["games"] = await asyncio.wait_for(_game_rows(games), timeout=5)
    except Exception:
        log.warning("Game weather lines failed")
        pack["games"] = [g.get("game") for g in games if g.get("game")]
    pack["asked"] = query or phrase or ""
    if pack.get("hours"):
        pack["live"] = (pack["hours"][0].get("stamp") or "") == datetime.now(TZ).strftime("%Y-%m-%dT%H:00")
    pack["brief"] = weather_brief(pack)
    pack["now"] = pack["hours"][0]["temp"] if pack.get("hours") else None
    return pack


# ---- matchup ------------------------------------------------------------------------------------

async def team_injuries(path: str, team_name: str) -> list[dict]:
    out = []
    try:
        raw = await cached_json(ESPN_INJURIES.format(path=path), {}, 900)
    except Exception:
        return out
    for team in raw.get("injuries") or []:
        if norm_team(team.get("displayName") or "") != norm_team(team_name):
            continue
        for inj in team.get("injuries") or []:
            status = inj.get("status")
            if isinstance(status, dict):
                status = status.get("name")
            ath = (inj.get("athlete") or {}).get("displayName")
            if ath and status and str(status).lower() != "active":
                out.append({"name": ath, "status": str(status)})
    return out


async def matchup_embed(guild_id: Optional[int], path: str, ev: dict) -> discord.Embed:
    away = next(t for t in ev["teams"] if not t["home"])
    home = next(t for t in ev["teams"] if t["home"])
    when = event_time(ev)
    e = discord.Embed(title=f"🆚 {away['short']} @ {home['short']}", color=BRAND,
                      description=kickoff_line(ev))
    for t in (away, home):
        rec = " · ".join(f"{k} {v}" for k, v in (t.get("records") or {}).items())
        e.add_field(name=t["short"], value=rec or "-")
    v = ev.get("venue") or {}
    if v.get("name"):
        line = v["name"] + (f", {v['city']}" if v.get("city") else "")
        if v.get("indoor"):
            line += " · 🏟️ indoors"
        elif when and v.get("city") and ev.get("state") == "pre" and when - datetime.now(timezone.utc) < timedelta(days=7):
            w = await kickoff_weather(v["city"], v.get("state") or "", when)
            if w:
                line += f"\n🌤️ Kickoff: {weather_line(w)}"
        e.add_field(name="Venue", value=clip(line, 1024), inline=False)
    b2b = await b2b_team_ids(path, when or datetime.now(timezone.utc))
    tired = [t["short"] for t in ev["teams"] if t["id"] in b2b]
    if tired and ev.get("state") == "pre":
        e.add_field(name="🔁 Back-to-back", value=", ".join(tired) + " played yesterday", inline=False)
    for t in (away, home):
        inj = await team_injuries(path, t.get("name") or t["short"])
        if inj:
            e.add_field(name=f"🚑 {t['short']} injuries", inline=False,
                        value=clip(", ".join(f"{x['name']} ({x['status']})" for x in inj[:12]), 1024))
    if guild_id:
        cons = consensus_for(guild_id, ev)
        if cons:
            e.add_field(name="👥 The group's open picks on this game", value=clip(cons, 1024), inline=False)
    return e


# ---- consensus ----------------------------------------------------------------------------------

def leg_side(text: str, ev: dict) -> Optional[str]:
    """Which side of this game a leg is on: a team's short name, 'Over' or 'Under'."""
    leg = parse_simple_leg(text)
    if not leg:
        return None
    if leg["kind"] == "total":
        side = leg["side"].title()
        if leg["negate"]:
            side = "Under" if side == "Over" else "Over"
        return f"{side} {leg['line']:g}"
    for i, t in enumerate(ev["teams"]):
        if team_matches(leg["team"], t):
            if leg["kind"] == "team_total":
                return f"{t['short']} team total {leg['side']}"
            backed = t if not leg["negate"] else ev["teams"][1 - i]
            return backed["short"]
    return None


def consensus_for(guild_id: int, ev: dict) -> str:
    counts: dict[str, list[str]] = {}
    for p in db().execute("SELECT * FROM picks WHERE guild_id = ? AND status = 'open' AND (hidden IS NULL OR hidden = 0)",
                          (guild_id,)).fetchall():
        texts = [x["text"] for x in get_legs(p["id"]) if x["status"] == "open"] or [p["description"]]
        teams_here = {norm_team(t["short"]) for t in ev["teams"]} | {a for t in ev["teams"] for a in t["aliases"]}
        for text in texts:
            side = leg_side(text, ev)
            if not side:
                continue
            leg = parse_simple_leg(text)
            if leg["kind"] == "total" and not any(team_matches(x, t) for x in paren_teams(text) + [
                    (parse_simple_leg(o) or {}).get("team", "") for o in texts] for t in ev["teams"]):
                continue
            counts.setdefault(side, []).append(p["bettor_name"])
    total = sum(len(v) for v in counts.values())
    lines = []
    for side, who in sorted(counts.items(), key=lambda kv: -len(kv[1])):
        pct = len(who) / total * 100
        bar = "█" * max(1, int(round(pct / 10)))
        lines.append(f"**{side}** {bar} {pct:.0f}% ({', '.join(sorted(set(who)))})")
    return "\n".join(lines)


async def consensus_embed(guild_id: int) -> discord.Embed:
    e = discord.Embed(title="👥 Group consensus · tonight", color=BRAND)
    now = datetime.now(TZ)
    found = 0
    for path in group_leagues(guild_id):
        for ev in await fetch_scoreboard(path, now):
            if ev["final"]:
                continue
            c = consensus_for(guild_id, ev)
            if c and found < 20:
                if add_field_capped(e, clip(today_line(ev).replace("`", ""), 256), clip(c, 1024)):
                    found += 1
    if not found:
        e.description = "Nobody has an open moneyline, spread or total on today's games."
    e.set_footer(text="Built from open picks (hidden picks left out)")
    return e


