_FREE_NAME_TOKEN = re.compile(r"^(?:[A-ZÀ-ÞĀ-ž][A-Za-zÀ-ÿĀ-ž'’.\-]*|[A-Z]{2,3})$")


def slip_reader_on() -> bool:
    """Can the bot read screenshots at all (free scan, Gemini or Claude)?"""
    return any((r == "scan" and TESSERACT) or (r == "gemini" and GEMINI_API_KEY) or (r == "claude" and ai_enabled())
               for r in SLIP_READERS)


def free_count(how: str) -> None:
    key = f"slipreads:{datetime.now(TZ).date().isoformat()}"
    try:
        counts = json.loads(get_setting(0, key) or "{}")
    except ValueError:
        counts = {}
    counts[how] = counts.get(how, 0) + 1
    set_setting(0, key, json.dumps(counts))


def free_counts_line() -> str:
    try:
        counts = json.loads(get_setting(0, f"slipreads:{datetime.now(TZ).date().isoformat()}") or "{}")
    except ValueError:
        counts = {}
    names = {"scan": "free scan", "scan_confirm": "free scan (confirmed by hand)", "fail": "failed reads",
             "gemini": "Gemini (free)",
             "claude": "Claude", "ask_gemini": "questions on Gemini (free)", "ask_claude": "questions on Claude",
             "ask_groq": "questions on Groq (free)"}
    parts = [f"{counts[k]} {names.get(k, k)}" for k in ("scan", "scan_confirm", "fail", "gemini", "claude", "ask_groq",
                                                         "ask_gemini", "ask_claude") if counts.get(k)]
    on = [names[r] if r != "scan" else "free scan" for r in SLIP_READERS
          if (r == "scan" and TESSERACT) or (r == "gemini" and GEMINI_API_KEY) or (r == "claude" and ai_enabled())]
    return (" · ".join(parts) or "none yet") + "\nReaders on, in order: " + (" → ".join(on) or "none (the form only)")


# ---- the free text scan (pure: runs in a thread, never touches the database) -------------------------

def free_prepare(raw: bytes):
    """(colour image, OCR-ready greyscale image, scale) with dark mode flipped, upscaled so small print reads."""
    from PIL import Image, ImageOps, ImageFilter, ImageStat
    try:
        from pillow_heif import register_heif_opener
        register_heif_opener()
    except Exception:
        pass
    img = Image.open(io.BytesIO(raw))
    sec_check_image(img)
    img.seek(0)
    img = ImageOps.exif_transpose(img).convert("RGB")
    w, h = img.size
    scale = max(1.0, min(3.0, 1600 / max(1, w)))
    if scale > 1.05:
        img = img.resize((round(w * scale), round(h * scale)), Image.LANCZOS)
    grey = img.convert("L")
    if ImageStat.Stat(grey).mean[0] < 128:          # dark mode: Tesseract wants dark text on light
        grey = ImageOps.invert(grey)
    grey = ImageOps.autocontrast(grey, cutoff=1).filter(ImageFilter.UnsharpMask(radius=1.5, percent=80, threshold=2))
    return img, grey, scale


def _free_tess(img, psm: int, extra: Optional[list] = None, tsv: bool = True) -> str:
    buf = io.BytesIO()
    img.save(buf, "PNG")
    args = [TESSERACT, "stdin", "stdout", "--oem", "1", "--psm", str(psm), "-l", "eng"] + (extra or []) + (["tsv"] if tsv else [])
    try:
        r = subprocess.run(args, input=buf.getvalue(), capture_output=True, timeout=6)
    except subprocess.TimeoutExpired:
        return ""
    return r.stdout.decode("utf-8", "replace")


def _free_word_rows(grey, psm: int) -> list[dict]:
    out = []
    for row in _free_tess(grey, psm).splitlines()[1:]:
        f = row.split("\t")
        if len(f) < 12 or f[0] != "5" or not f[11].strip():
            continue
        try:
            out.append({"text": f[11].strip(), "conf": float(f[10]), "x": int(f[6]), "y": int(f[7]), "w": int(f[8]),
                        "h": int(f[9]), "line": (int(f[2]), int(f[3]), int(f[4]))})
        except ValueError:
            continue
    return out


def free_words(grey, psm: int = 4) -> list[dict]:
    """Every word Tesseract saw: {text, conf, x, y, w, h, line} with line = a key shared by words on one line.
    One layout only. A thin read is retried by the scan budget, not by stacking more passes here."""
    return _free_word_rows(grey, psm)


def free_lines(words: list[dict]) -> list[dict]:
    """Words grouped into lines, top to bottom: {words, text, y, h, x0, x1}."""
    groups: dict = {}
    for wd in words:
        groups.setdefault(wd["line"], []).append(wd)
    lines = []
    for ws in groups.values():
        ws.sort(key=lambda w: w["x"])
        lines.append({"words": ws, "text": " ".join(w["text"] for w in ws), "y": min(w["y"] for w in ws),
                      "h": max(w["h"] for w in ws), "x0": min(w["x"] for w in ws),
                      "x1": max(w["x"] + w["w"] for w in ws)})
    lines.sort(key=lambda ln: (ln["y"], ln["x0"]))
    return lines


def free_reocr_number(grey, wd: dict) -> Optional[str]:
    """Read one number box again, zoomed in, digits only (fixes '495' for '49.5')."""
    from PIL import Image
    pad = max(4, wd["h"] // 3)
    box = (max(0, wd["x"] - pad), max(0, wd["y"] - pad), wd["x"] + wd["w"] + pad, wd["y"] + wd["h"] + pad)
    crop = grey.crop(box)
    crop = crop.resize((crop.width * 3, crop.height * 3), Image.LANCZOS)
    txt = _free_tess(crop, 7, ["-c", "tessedit_char_whitelist=0123456789."], tsv=False).strip()
    return txt if re.fullmatch(r"\d{1,4}(?:\.\d)?", txt) else None


def free_arrow(img, box: tuple) -> Optional[str]:
    """'over' for an up arrow, 'under' for a down arrow, from where the arrow's head (its widest part) sits."""
    x0, y0, x1, y1 = (int(v) for v in box)
    x0, y0, x1, y1 = max(0, x0), max(0, y0), min(img.width, x1), min(img.height, y1)
    if x1 - x0 < 4 or y1 - y0 < 6:
        return None
    crop = img.crop((x0, y0, x1, y1)).convert("L")
    px = crop.load()
    w, h = crop.size
    vals = sorted(px[i, j] for i in range(w) for j in range(h))
    bg = vals[len(vals) // 2]
    rows = []
    for j in range(h):
        rows.append(sum(1 for i in range(w) if abs(px[i, j] - bg) > 60))
    ink = [j for j, n in enumerate(rows) if n]
    if len(ink) < 5:
        return None
    top, bottom = ink[0], ink[-1]
    span = bottom - top + 1
    third = max(1, span // 3)
    upper = sum(rows[top:top + third])
    lower = sum(rows[bottom - third + 1:bottom + 1])
    if upper > lower * 1.25:
        return "over"
    if lower > upper * 1.25:
        return "under"
    return None


def free_green(img, wd: dict) -> float:
    """How much of a word's button is filled green (the picked More/Less on PrizePicks' builder)."""
    pad = wd["h"]
    crop = img.crop((max(0, wd["x"] - pad), max(0, wd["y"] - pad // 2), wd["x"] + wd["w"] + pad,
                     wd["y"] + wd["h"] + pad // 2))
    px = list(crop.getdata())
    green = sum(1 for r, g, b in px if g > 150 and g > r + 50 and g > b + 50)
    return green / max(1, len(px))


def free_green_side(img, top: float, bottom: float) -> Optional[str]:
    """On the builder screen the picked button is filled green: Less sits left of More."""
    w = img.width
    crop = img.crop((int(w * 0.55), max(0, int(top)), w, min(img.height, int(bottom))))
    pts = [i % crop.width for i, (r, g, b) in enumerate(crop.getdata()) if g > 150 and g > r + 50 and g > b + 50]
    if len(pts) < 50:
        return None
    centre = (sum(pts) / len(pts) + w * 0.55) / w
    return "over" if centre > 0.78 else "under"


def _free_numtext(t: str) -> str:
    """'«12.5' -> '12.5', '49,5' -> '49.5' (icons and punctuation OCR glues onto a number)."""
    if re.search(r"[#:$%/x]|\d\s*['’]?\s*[a-wyz]", t, re.I):   # jersey numbers, times, money, '37.5x', '6pm', "180's"
        return ""
    core = re.sub(r"^[^\d]+|[^\d]+$", "", t).replace(",", ".")
    lead = re.match(r"^[^\d]*", t).group(0)
    if lead[-1:] in (".", ",") and lead[-2:-1] in ("", "O", "o", "D", "Q"):
        core = "0." + core                     # "O.5" / ".5" is 0.5
    return core


def _free_stat_in(text: str) -> Optional[tuple[str, int]]:
    """(stat name, where it starts) for the stat printed in this line, if any."""
    text = (text or "").replace("’", "'").replace("`", "'")
    for name, rx in _FREE_STAT_RX:
        m = rx.search(text)
        if m:
            return name, m.start()
    return None


def free_glyph_side(text: str) -> Optional[str]:
    """The over/under arrow when OCR kept the glyph, which is more reliable than guessing from pixels."""
    if re.search(r"[↑▲]", text or ""):
        return "over"
    if re.search(r"[↓▼]", text or ""):
        return "under"
    return None


_FREE_LABEL_JUNK = re.compile(
    r"\b(?:vs|am|pm|refund|payout|prizepicks|flex|power|play|pick|picks|entry|slide|early|self|available|"
    r"time|remaining|mlb|nba|nbap|nhl|wnba|nfl|cfb|cbb|ncaaf|ncaab|tennis|darts|cricket|soccer|today|"
    r"tomorrow|mon|tue|wed|thu|fri|sat|sun)\b", re.I)


def _free_label(text: str) -> Optional[str]:
    """A stat printed in the right-hand box that isn't in the known list, kept so the leg still logs."""
    raw = (text or "").replace("’", "'")
    if re.search(r"\d{1,2}:\d{2}|\$", raw):
        return None
    known = _free_stat_in(raw)
    if known:
        return known[0]
    t = " ".join(re.sub(r"[^A-Za-z0-9+.'’\- ]", " ", raw).split())
    if not t or len(t) < 2 or len(t) > 28 or not re.search(r"[A-Za-z]", t):
        return None
    words = t.split()
    if not 1 <= len(words) <= 4 or _FREE_LABEL_JUNK.search(t):
        return None
    return t


def _free_combo_name(line: dict) -> Optional[str]:
    """'Gabby Williams + Rhyne Howard' is one combo card, even when the stat sits on the same line."""
    text = re.sub(r"\s+", " ", line.get("text") or "").strip()
    m = re.search(
        r"([A-Z][\w'’.\-]+(?:\s+[A-Z][\w'’.\-]+){0,2})\s*\+\s*([A-Z][\w'’.\-]+(?:\s+[A-Z][\w'’.\-]+){0,2})",
        text)
    if not m:
        return None
    a, b = m.group(1), m.group(2)
    if len(a.split()) < 2 or len(b.split()) < 2 or _free_stat_in(a) or _free_stat_in(b):
        return None
    return f"{a} + {b}"


def _free_named(line: dict, max_x: Optional[float] = None) -> Optional[str]:
    return _free_combo_name(line) or _free_name(line, max_x)


def _free_name(line: dict, max_x: Optional[float] = None) -> Optional[str]:
    """A player's name at the start of a line (skipping OCR noise from photos and icons)."""
    text = " ".join(t for t in line["text"].split() if not ("@" in t and free_pill_num(t)))
    if re.search(r"vs\b|\d{1,2}:\d{2}|@|\$|#\s?\d", text, re.I) or re.search(
            r"\b(defender|midfielder|attacker|forward|goalkeeper|guard|center|qb|rb|wr|te|lw|rw|sp|rp)\b", line["text"], re.I):
        return None                            # a game header, an amount, or a team/position/jersey line
    toks = [w["text"].strip(",;:|()[]{}©@&*") for w in line["words"] if not ("@" in w["text"] and free_pill_num(w["text"]))
            and (max_x is None or w["x"] < max_x)]
    best: list[str] = []
    run: list[str] = []
    for t in toks + [""]:
        ok = bool(t) and _FREE_NAME_TOKEN.match(t) and t.lower() not in _FREE_JUNK and not any(c.isdigit() for c in t)
        if ok:
            run.append(t)
            continue
        while run and len(run[-1]) <= 2 and run[-1] not in ("Jr", "Sr", "II", "IV") and len(run) > 1:
            run.pop()                          # trailing icon noise like "Vv"
        while len(run) > 2 and len(run[0]) <= 2 and not run[0].isupper():
            run.pop(0)                         # leading noise like "Ps" (but "OG Anunoby", "AJ Brown" stay)
        while len(run) > 2 and len(run[0]) == 1:
            run.pop(0)                         # a lone letter from the photo: "A Shohei Ohtani"
        if len(run) >= 4 and len(run[0]) <= 3 and not run[0].isupper() and run[-1] in ("Jr", "Sr", "II", "III", "IV"):
            run.pop(0)                         # "Aan James Cook III": the scrap before a full name with a suffix
        joined = " ".join(run)
        if len(run) >= 2 and not _free_stat_in(joined) and sum(len(x) for x in run) > len(" ".join(best).replace(" ", "")):
            best = run[:]
        run = []
    if len(best) < 2 or len(best) > 4:
        return None
    if all(x.isupper() for x in best):        # "DAL QB", "TB RB": team and position, not a name
        return None
    if _free_stat_in(" ".join(best)):         # "Pass Yards" is a stat, not a person
        return None
    return " ".join(best)


_FREE_PILL = re.compile(r"^[^\w]*[vVtTrRlI1↑↓]?([0-9oOsS]{1,2}(?:[.,][0-9oOsS])?)$")


def free_pill_num(text: str) -> Optional[str]:
    """A number from the pick's box with the over/under arrow glued on: '@r15' -> '15', '@vos' -> '05'."""
    t = _free_numtext(text)
    if t:
        return t
    m = _FREE_PILL.match(text or "")
    if not m or not re.search(r"[sS5]", m.group(1)):
        return None
    return m.group(1).translate(str.maketrans("oOsS,", "0055."))


def free_slip_result(full: str) -> tuple[str, Optional[float], bool]:
    """(status, returned, hint). A finished win or loss has to say so. 'to win' on an open entry is not a win.
    hint is true when the words look like a result but are not clear enough to grade."""
    low = (full or "").lower()
    cleaned = re.sub(r"\b(faceoffs?|games?|sets?|maps?)\s+won\b", " ", low)
    cleaned = re.sub(r"\bto\s+win\b", " ", cleaned)
    win = bool(re.search(
        r"\b(you won|entry won|slip won|we won|cashed|winner|payout paid|paid out)\b", cleaned))
    loss = bool(re.search(
        r"\b(you lost|entry lost|slip lost|lost entry|did not hit|didn't hit|busted|better luck)\b", cleaned))
    if re.search(r"(?:^|\n)\s*won\b", cleaned):
        win = True
    if re.search(r"(?:^|\n)\s*lost\b", cleaned):
        loss = True
    # PrizePicks prints a Win or Loss chip on a settled card. "to win" was already removed.
    if re.search(r"\bwin\b", cleaned):
        win = True
    if re.search(r"\bloss\b", cleaned):
        loss = True
    paid = re.search(r"\$\s*([\d,]+(?:\.\d{1,2})?)\s*paid\s*\$\s*([\d,]+(?:\.\d{1,2})?)", full or "", re.I)
    paid_back = as_amount(paid.group(2)) if paid else None
    if paid and not loss:
        win = True
    if win and loss:
        return "open", None, True
    if re.search(r"\brefunded\b", cleaned) and not win and not loss:
        return "push", None, False
    if win:
        m = re.search(r"(?:you won|cashed|paid out|payout paid)\s*\$?\s*([\d,]+\.\d{2})", full, re.I)
        if not m:
            m = re.search(r"(?:^|\n)\s*won\s*\$?\s*([\d,]+\.\d{2})", full, re.I)
        if not m:
            m = re.search(r"(?:^|\n)\s*won\s*(?:\n\s*)\$([\d,]+\.\d{2})", full, re.I)
        returned = paid_back if paid_back is not None else (as_amount(m.group(1)) if m else None)
        return "win", returned, False
    if loss:
        return "loss", 0.0, False
    hint = bool(re.search(r"\b(won|lost|cashed|busted)\b", cleaned))
    return "open", None, hint


def free_parse(words: list[dict], img, grey) -> Optional[dict]:
    """A slip from the scan's words, in the same shape the AI readers return, plus '_unsure' with the reasons
    when anything didn't read cleanly. None when it doesn't look like a slip at all."""
    lines = free_lines(words)
    if not lines:
        return None
    full = "\n".join(ln["text"] for ln in lines)
    low = full.lower()
    unsure: list[str] = []
    # platform and entry type
    platform = None
    if "prizepicks" in low or re.search(r"\b(power|flex) play\b", low) or re.search(r"\bless\b.*\bmore\b", low):
        platform = "PrizePicks"
    elif "underdog" in low or re.search(r"\bhigher\b|\blower\b", low):
        platform = "Underdog"
    for book in ("FanDuel", "DraftKings", "BetMGM", "Caesars", "Fanatics", "bet365", "ESPN BET", "Hard Rock",
                 "BetRivers", "Kalshi", "Sleeper", "Dabble", "Betr", "ParlayPlay"):
        if book.lower() in low:
            platform = book
            break
    if platform is None and (re.search(r"\bkalshi\b", low)
                             or (re.search(r"\b(yes|no)\b", low)
                                 and re.search(r"\b\d{1,3}\s*(?:¢|cents)\b", low))):
        platform = "Kalshi"
    has_flex, has_power = bool(re.search(r"\bflex\b|\binsured\b", low)), bool(re.search(r"\bpower\b|\bstandard\b", low))
    entry_type = None if has_flex and has_power else ("flex" if has_flex else ("power" if has_power else None))
    m = re.search(r"(\d{1,2})\s*-?\s*pick", low)
    want = int(m.group(1)) if m and 2 <= int(m.group(1)) <= 12 else None
    # amounts: "$2 paid $3" on a settled card, or "$25 to win $450" on an open entry
    cost = payout = None
    paid_m = re.search(_FREE_MONEY + r"\s*paid\s*" + _FREE_MONEY, full, re.I)
    if paid_m:
        cost, payout = as_amount(paid_m.group(1)), as_amount(paid_m.group(2))
    m = re.search(_FREE_MONEY + r"\s*to\s*(?:win|pay)\s*" + _FREE_MONEY, full, re.I) if not paid_m else None
    if m:
        cost, payout = as_amount(m.group(1)), as_amount(m.group(2))
    elif not paid_m:
        for k, ln in enumerate(lines):
            if re.search(r"entry\s*fee|wager|stake", ln["text"], re.I):
                amounts = re.findall(_FREE_MONEY + r"|(?<![\d.])(\d+\.\d{2})(?!\d)",
                                     " ".join(x["text"] for x in lines[k:k + 3]))
                vals = [as_amount(a or b) for a, b in amounts]
                vals = [v for v in vals if v]
                if len(vals) >= 2:
                    cost, payout = vals[0], vals[1]
                elif vals:
                    cost = vals[0]
                break
    if cost is None:
        unsure.append("the amount risked")
    if payout is None:
        unsure.append("the payout")
    if len(re.findall(r"\b(?:entry fee|to win|power play|flex play)\b", low)) >= 4:
        unsure.append("more than one slip in this photo")
    # legs: anchor on each stat name, take the line number before it, the name above it, and the side
    legs: list[str] = []
    used_lines: set = set()       # a name line belongs to one leg; the same player can be on two lines
    num_hs = sorted(w["h"] for w in words if _FREE_NUM.match(_free_numtext(w["text"])))
    builder = bool(re.search(r"\bless\b", low) and re.search(r"\bmore\b", low))
    used_rows: set = set()
    for k, ln in enumerate(lines):
        blob, joined = ln["text"], False
        if not _free_stat_in(blob) and ln["x0"] > 0.40 * img.width:
            extra = []
            for j in range(k + 1, min(len(lines), k + 3)):
                nxt = " ".join(w["text"] for w in lines[j]["words"] if w["x"] > 0.42 * img.width)
                if not nxt:
                    break
                extra.append(nxt)
                if _free_stat_in(blob + " " + " ".join(extra)):
                    blob = blob + " " + " ".join(extra)
                    joined = True
                    break
        st = _free_stat_in(blob)
        if not st:
            continue
        stat, at = st
        # where the stat sits: on cards with the line in a box on the right, only numbers in that box count
        pos, stat_x = 0, None
        for w in ln["words"]:
            if pos >= at - 1 and stat_x is None:
                stat_x = w["x"]
            pos += len(w["text"]) + 1
        right = stat_x is not None and stat_x > 0.55 * img.width
        if joined and at >= len(ln["text"]):
            right = True
        # the number: on this line before the stat, else the line(s) just above
        cand_lines = [ln] + [lines[j] for j in range(k - 1, max(-1, k - 3), -1)]
        num_words, src = [], None
        whole = None                                          # a bare whole number, used only if no decimal is near
        hn = num_hs[len(num_hs) // 2] if num_hs else 25
        if right:
            for cl in cand_lines[1:]:
                box_ws = [w for w in cl["words"] if w["x"] > 0.55 * img.width]
                if not box_ws:
                    continue
                rw = max(box_ws, key=lambda w: w["x"] + w["w"])
                clean = _free_numtext(rw["text"])
                if "." in clean or len(re.sub(r"\D", "", clean)) > 2:
                    break                                     # a clean number: the usual path reads it
                rr, cy = rw["x"] + rw["w"], rw["y"] + rw["h"] / 2
                fake = {"x": int(rr - 1.8 * hn), "y": int(cy - 0.6 * hn), "w": int(1.8 * hn), "h": int(1.2 * hn),
                        "text": rw["text"], "conf": 100, "_glued": True}
                got = free_reocr_number(grey, fake)
                if got and "." in got:
                    fake["_num"] = got
                    num_words, src = [fake], cl
                break
        for idx, cl in enumerate([] if num_words else cand_lines):
            ws = [w for w in cl["words"] if _FREE_NUM.match(_free_numtext(w["text"]))]
            if right:
                ws = []
                for w in cl["words"]:
                    if w["x"] < 0.55 * img.width:
                        continue                              # avatar and jersey scraps on the left
                    pn = free_pill_num(w["text"])
                    if pn and _FREE_NUM.match(pn):
                        w["_num"] = pn
                        w["_glued"] = not _free_numtext(w["text"])
                        ws.append(w)
            if cl is ln:
                cut = len(ln["text"][:at])
                pos, kept = 0, []
                for w in cl["words"]:
                    if pos < cut and w in ws:
                        kept.append(w)
                    pos += len(w["text"]) + 1
                ws = kept
            ws = [w for w in ws if not re.search(r"#\s*$", cl["text"][:cl["text"].find(w["text"])])]
            dec = [w for w in ws if re.search(r"[.,]\d$", w.get("_num") or _free_numtext(w["text"]))]
            if dec:
                num_words, src = dec, cl
                break
            if ws and whole is None:
                whole = (ws, cl)
            # "13 Rebs+Asts" is a real line. Don't walk past it to the previous leg's 2.5.
            if ws and idx <= 1:
                num_words, src = ws, cl
                break
        if not num_words and whole:
            num_words, src = whole
        if not num_words:
            continue
        wd = max(num_words, key=lambda w: w["x"])            # the new line, never a crossed-out old one
        txt = wd.get("_num") or _free_numtext(wd["text"])
        again = free_reocr_number(grey, wd)
        if again and (("." in again) or "." not in txt):
            txt = again
        try:
            value = float(txt)
        except ValueError:
            continue
        if platform == "PrizePicks" and right and re.fullmatch(r"\d5", txt):
            value = value / 10                                # the dot lost next to the arrow: '25' is 2.5
        if "." not in txt and value >= 100 and txt.endswith("5") and stat not in ("Pass Yards", "Pass+Rush Yds",
                                                                                   "Rush+Rec Yds", "Pitches Thrown"):
            value = value / 10                                # '495' Rec Yards is 49.5
        # the player: the nearest name at or above the number's line
        name, name_at = None, None
        start = lines.index(src)
        order = [start] + ([start + 1] if start + 1 < len(lines) and lines[start + 1]["y"] - src["y"] < 1.2 * src["h"]
                           else []) + list(range(start - 1, max(-1, start - 4), -1))
        for j in order:
            name = _free_named(lines[j], 0.55 * img.width if right else None)
            if name and j not in used_lines:
                name_at = j
                break
            name = None
        if not name:
            # The line above this one already logged this same number and stat. Don't flag it twice.
            if not any(f" {value:g} " in f" {lg} " and stat.lower() in lg.lower() for lg in legs):
                unsure.append(f"a player's name near {value:g} {stat}")
            continue
        used_lines.add(name_at)
        # the side: an arrow glyph OCR kept, else More/Less words (the green one when both show), else the pixels
        side = None
        lo = min(start, name_at if name_at is not None else start)
        near = [w for j in range(lo, min(len(lines), k + 2)) for w in lines[j]["words"]]
        for w in near:
            side = free_glyph_side(w["text"])
            if side:
                break
        words_low = {w["text"].lower().strip("+-↑↓"): w for w in near}
        if side is None and "more" in words_low and "less" in words_low:
            gm, gl = free_green(img, words_low["more"]), free_green(img, words_low["less"])
            side = "over" if gm > gl * 1.5 and gm > 0.08 else ("under" if gl > gm * 1.5 and gl > 0.08 else None)
        elif side is None and (("more" in words_low) ^ ("less" in words_low) or not builder):
            for word, s in (("more", "over"), ("over", "over"), ("higher", "over"), ("less", "under"),
                            ("under", "under"), ("lower", "under")):
                if word in words_low:
                    side = s
                    break
        if side is None and builder:
            top = lines[lo]["y"] - src["h"]
            bottom = ln["y"] + 2 * ln["h"]
            side = free_green_side(img, top, bottom)
        if side is None:
            left = [w for w in src["words"] if w["x"] + w["w"] <= wd["x"] and w["x"] > wd["x"] - 6 * wd["h"]]
            nums_left = [w for w in left if _FREE_NUM.match(_free_numtext(w["text"]))
                         and len(_free_numtext(w["text"])) > 1]      # a lone "4"/"1" is the arrow, misread
            anchor = min(nums_left, key=lambda w: w["x"]) if nums_left else wd
            glyph = [w for w in left if w not in nums_left and w["x"] + w["w"] <= anchor["x"] + 2
                     and w["x"] > anchor["x"] - 3 * wd["h"]]
            if glyph:
                g = max(glyph, key=lambda w: w["x"])
                box = (g["x"] - 4, wd["y"] - wd["h"] * 0.4, g["x"] + g["w"] + 4, wd["y"] + wd["h"] * 1.4)
            else:
                box = (anchor["x"] - 2.2 * wd["h"], wd["y"] - wd["h"] * 0.4, anchor["x"] - 0.15 * wd["h"],
                       wd["y"] + wd["h"] * 1.4)
            side = free_arrow(img, box)
        if side is None and right and wd.get("_glued"):
            # the arrow glued into the number's word: find it just left of the digits, from the box's right edge
            digits = len(f"{value:g}") + (0 if "." in f"{value:g}" else 1)
            rr, cy = wd["x"] + wd["w"], wd["y"] + wd["h"] / 2
            nw = digits * 0.6 * hn
            side = free_arrow(img, (rr - nw - 1.9 * hn, cy - 0.9 * hn, rr - nw - 0.15 * hn, cy + 0.9 * hn))
        if side is None:
            unsure.append(f"over or under for {name}")
            side = "over"
        if num_hs and wd["h"] > 1.35 * num_hs[len(num_hs) // 2] and wd.get("conf", 100) < 60:
            unsure.append(f"the line for {name}")           # an arrow glued onto the number
        if stat.lower().startswith("anytime") and value > 1.5:
            unsure.append(f"the line for {name}")
            value = 0.5
        leg = f"{name} {side} {value:g} {'Anytime TD' if stat.lower().startswith('anytime') else stat}"
        if leg not in legs:
            legs.append(leg)
            used_rows.add(k)
            if joined:
                used_rows.add(min(k + 1, len(lines) - 1))
                used_rows.add(min(k + 2, len(lines) - 1))
    # A stat the list has never seen (a new PrizePicks market) still becomes a leg when it sits in the right box.
    for k, ln in enumerate(lines):
        if k in used_rows or ln["x0"] < 0.48 * img.width:
            continue
        stat = _free_label(ln["text"])
        if not stat:
            continue
        num_w = []
        src = None
        for j in range(k, max(-1, k - 3), -1):
            ws = [w for w in lines[j]["words"] if w["x"] > 0.50 * img.width and _FREE_NUM.match(_free_numtext(w["text"]))]
            if ws:
                num_w, src = ws, lines[j]
                break
        if not num_w:
            continue
        wd = max(num_w, key=lambda w: w["x"])
        try:
            value = float(_free_numtext(wd["text"]))
        except ValueError:
            continue
        name, name_at = None, None
        for j in range(k - 1, max(-1, k - 5), -1):
            name = _free_named(lines[j], 0.55 * img.width)
            if name and j not in used_lines:
                name_at = j
                break
            name = None
        if not name:
            continue
        side = free_glyph_side(ln["text"]) or free_glyph_side(wd["text"])
        if side is None:
            side = free_arrow(img, (wd["x"] - 2.2 * wd["h"], wd["y"] - wd["h"] * 0.4, wd["x"] - 2, wd["y"] + wd["h"] * 1.4))
        if side is None:
            unsure.append(f"over or under for {name}")
            side = "over"
        leg = f"{name} {side} {value:g} {stat}"
        if leg not in legs:
            legs.append(leg)
            used_lines.add(name_at)
            used_rows.add(k)
    status, returned, result_hint = free_slip_result(full)
    if status == "win" and returned is not None and payout is None:
        payout = returned
        unsure = [u for u in unsure if u != "the payout"]
    if not legs:
        if platform and (cost or payout or status != "open"):
            return {"is_slip": True, "platform": platform, "sport": None, "description": "Slip", "legs": [],
                    "cost": cost, "payout": payout, "status": status, "returned": returned, "game_date": None,
                    "entry_type": entry_type, "placed": True, "_unsure": ["the picks"], "_how": "scan",
                    "_result_hint": result_hint}
        return None
    if want and len(legs) != want:
        unsure.append(f"all {want} picks (I found {len(legs)})")
    if not platform:
        platform = "PrizePicks" if entry_type else "Other"
        unsure.append("which app it's from")
    placed = not re.search(r"\bsubmit\b|place entry|add picks|entry fee", low)
    n = want or len(legs)
    desc = (f"{n}-Pick {'Flex' if entry_type == 'flex' else 'Power'} Play" if platform in ("PrizePicks", "Underdog")
            else f"{n}-leg slip" if n > 1 else legs[0])
    sports = []
    for label, rx in (("NFL", r"\bNFL(?:SZN)?\b"), ("NBA", r"\bNBA(?:SZN|P)?\b|\bNBAP\b"), ("NHL", r"\bNHL\b"), ("MLB", r"\bMLB\b"),
                      ("WNBA", r"\bWNBA\b"), ("SOCCER", r"\bSOCCER\b"), ("CFB", r"\bCFB\b|\bNCAAF\b"),
                      ("CBB", r"\bCBB\b|\bNCAAB\b"), ("Tennis", r"\bTENNIS\b"), ("Darts", r"\bDARTS\b"),
                      ("Cricket", r"\bCRICKET\b"), ("Table Tennis", r"(?<![A-Za-z])TT(?![A-Za-z])")):
        if re.search(rx, full):
            sports.append(label)
    return {"is_slip": True, "platform": platform, "sport": ", ".join(s.title() if s == "SOCCER" else s for s in sports)
            or None, "description": desc, "legs": legs, "cost": cost, "payout": payout, "status": status,
            "returned": returned, "game_date": None, "entry_type": entry_type, "placed": placed,
            "_unsure": unsure, "_how": "scan", "_result_hint": result_hint}


_FREE_MINOR_UNSURE = ("which app it's from",)


def _free_scan_ready(slip) -> bool:
    """Scanner 3.0: first pass is enough when legs + cost are in and leftover notes are only minor
    (unknown app). Extra OCR still runs when a leg, the amount, or a real hole is missing."""
    if not slip or not slip.get("legs") or slip.get("cost") is None:
        return False
    holes = [u for u in (slip.get("_unsure") or [])
             if u not in _FREE_MINOR_UNSURE and not str(u).startswith("more than one slip")]
    return not holes


def _free_slip_parts(words: list[dict]) -> list:
    """Split one photo into separate slips when two pick-count headers sit far apart."""
    lines = free_lines(words)
    heads = [ln for ln in lines if re.search(r"\b\d{1,2}\s*-?\s*pick\b", ln["text"], re.I)]
    if len(heads) < 2:
        return [words]
    heads.sort(key=lambda ln: ln["y"])
    cuts = []
    for a, b in zip(heads, heads[1:]):
        if b["y"] - a["y"] >= 90:
            cuts.append((a["y"] + b["y"]) // 2)
    if not cuts:
        return [words]
    bounds = [0] + cuts + [10 ** 9]
    parts = []
    for lo, hi in zip(bounds, bounds[1:]):
        part = [w for w in words if lo <= w["y"] < hi]
        if part:
            parts.append(part)
    return parts or [words]


def free_scan(raw: bytes) -> Optional[dict]:
    """The whole free scan on one image (sync, for a worker thread). Scanner 2.0: a clean first pass
    is kept as-is; extra treatments (other contrast, a tighter crop, a second Tesseract layout) only
    run when that pass missed the slip or left holes, and they may fill those holes — they never
    replace a sure read with a different one. Scanner 3.0 skips those retries when the first pass
    already has legs and the amount. The whole scan stops after a few seconds so a chat reply isn't stuck typing."""
    started = time.monotonic()
    img, grey, _ = free_prepare(raw)
    words = free_words(grey)
    parts = _free_slip_parts(words)
    if len(parts) > 1:
        slips = []
        for part in parts[:4]:
            one = free_parse(part, img, grey)
            if one and one.get("legs"):
                slips.append(one)
        if len(slips) >= 2:
            head = slips[0]
            head["_extra"] = slips[1:]
            return head
    first = free_parse(words, img, grey)
    if _free_scan_ready(first):
        return first
    best = first
    # A first pass that already has legs only re-reads the bands that can fill the holes.
    # A blank first pass still looks at the whole photo.
    deadline = started + 6
    if time.monotonic() > deadline:
        return best
    retries = (_free_hole_bands(img, grey, first, deadline) if first and first.get("legs")
               else _free_scan_retries(img, grey, deadline))
    for extra in retries:
        if time.monotonic() - started > 6:
            break
        best = _free_fill(best, extra)
        best = _free_tidy(best)
        if _free_scan_ready(best):
            return best
    return best


def _free_hole_bands(img, grey, slip, deadline: float = 0) -> list:
    """Crops for a second pass. Each box is a hole (money, the player list, or the app name), never the whole photo."""
    from PIL import ImageEnhance, ImageOps
    unsure = [str(u) for u in (slip.get("_unsure") or [])]
    w, h = img.size
    boxes = []
    if any(u in ("the amount risked", "the payout") for u in unsure):
        boxes.append((0, int(h * 0.72), w, h))
    if any("name" in u or "over or under" in u or "picks (I found" in u for u in unsure):
        boxes.append((0, int(h * 0.12), w, int(h * 0.78)))
    if any(u == "which app it's from" for u in unsure):
        boxes.append((0, 0, w, max(40, int(h * 0.22))))
    out = []
    for box in boxes:
        if deadline and time.monotonic() > deadline:
            break
        bw, bh = box[2] - box[0], box[3] - box[1]
        if bw < 40 or bh < 40 or bw * bh >= w * h * 0.92:
            continue
        try:
            crop, cgrey = img.crop(box), grey.crop(box)
            punch = ImageOps.autocontrast(ImageEnhance.Contrast(cgrey).enhance(1.6), cutoff=1)
            out.append(free_parse(free_words(punch), crop, punch))
        except Exception:
            log.debug("Hole re-read failed", exc_info=True)
    return [s for s in out if s]


def _free_scan_retries(img, grey, deadline: float = 0) -> list:
    """Other looks at the same picture when the first pass wasn't enough. Each is a free_parse result or None."""
    from PIL import ImageEnhance, ImageOps, ImageFilter
    out = []
    if deadline and time.monotonic() > deadline:
        return out
    try:
        words6 = free_words(grey, 6)
        if words6:
            out.append(free_parse(words6, img, grey))
    except Exception:
        log.debug("Scan retry psm6 failed", exc_info=True)
    if deadline and time.monotonic() > deadline:
        return [s for s in out if s]
    crop = _free_focus(img)
    if crop is not None and crop.size != img.size:
        try:
            cgrey = ImageOps.autocontrast(crop.convert("L"), cutoff=1).filter(
                ImageFilter.UnsharpMask(radius=1.5, percent=80, threshold=2))
            from PIL import ImageStat
            if ImageStat.Stat(cgrey).mean[0] < 128:
                cgrey = ImageOps.invert(cgrey)
            out.append(free_parse(free_words(cgrey), crop, cgrey))
        except Exception:
            log.debug("Scan retry crop failed", exc_info=True)
    if deadline and time.monotonic() > deadline:
        return [s for s in out if s]
    try:
        punch = ImageEnhance.Contrast(grey).enhance(1.85)
        punch = ImageOps.autocontrast(punch, cutoff=2)
        out.append(free_parse(free_words(punch), img, punch))
    except Exception:
        log.debug("Scan retry contrast failed", exc_info=True)
    return [s for s in out if s]


def _free_focus(img):
    """Crop chrome off a tall phone screenshot (status bar / home indicator / side wallpaper)."""
    w, h = img.size
    if h < 1.7 * w:
        return None
    return img.crop((int(w * 0.02), int(h * 0.05), int(w * 0.98), int(h * 0.94)))


def _free_leg_key(leg: str) -> str:
    return re.sub(r" (over|under) [\d.]+ ", " ", (leg or "").lower())


def _free_fill(base: Optional[dict], extra: Optional[dict]) -> Optional[dict]:
    """Copy amounts and missing legs from extra into base. Never drops what base already read."""
    if extra is None:
        return base
    if base is None:
        return extra
    out = dict(base)
    out["legs"] = list(base.get("legs") or [])
    out["_unsure"] = list(base.get("_unsure") or [])
    if out.get("cost") is None and extra.get("cost") is not None:
        out["cost"] = extra["cost"]
        out["_unsure"] = [u for u in out["_unsure"] if u != "the amount risked"]
    if out.get("payout") is None and extra.get("payout") is not None:
        out["payout"] = extra["payout"]
        out["_unsure"] = [u for u in out["_unsure"] if u != "the payout"]
    if not out.get("platform") and extra.get("platform"):
        out["platform"] = extra["platform"]
        out["_unsure"] = [u for u in out["_unsure"] if u != "which app it's from"]
    have = {_free_leg_key(lg) for lg in out["legs"]}
    for lg in extra.get("legs") or []:
        k = _free_leg_key(lg)
        if k and k not in have:
            out["legs"].append(lg)
            have.add(k)
    if extra.get("entry_type") and not out.get("entry_type"):
        out["entry_type"] = extra["entry_type"]
    if extra.get("sport") and not out.get("sport"):
        out["sport"] = extra["sport"]
    if extra.get("status") in ("win", "loss", "push") and out.get("status") not in ("win", "loss", "push"):
        out["status"] = extra["status"]
        if extra.get("returned") is not None:
            out["returned"] = extra["returned"]
        out["_result_hint"] = False
    elif extra.get("_result_hint") and out.get("status") not in ("win", "loss", "push"):
        out["_result_hint"] = True
    return out


def _free_tidy(slip: Optional[dict]) -> Optional[dict]:
    """Drop unsure flags that the fill-in pass resolved, and rebuild the header description."""
    if not slip:
        return slip
    unsure = list(slip.get("_unsure") or [])
    if slip.get("cost") is not None:
        unsure = [u for u in unsure if u != "the amount risked"]
    if slip.get("payout") is not None:
        unsure = [u for u in unsure if u != "the payout"]
    if slip.get("platform"):
        unsure = [u for u in unsure if u != "which app it's from"]
    legs = slip.get("legs") or []
    for u in list(unsure):
        m = re.search(r"all (\d+) picks \(I found (\d+)\)", u)
        if m and int(m.group(1)) == len(legs):
            unsure = [x for x in unsure if "picks (I found" not in x]
            break
    slip["_unsure"] = unsure
    n = len(legs)
    entry = slip.get("entry_type")
    platform = slip.get("platform") or "Other"
    if n and platform in ("PrizePicks", "Underdog"):
        slip["description"] = f"{n}-Pick {'Flex' if entry == 'flex' else 'Power'} Play"
    elif n > 1:
        slip["description"] = f"{n}-leg slip"
    elif n == 1:
        slip["description"] = legs[0]
    return slip


# ---- names: the scan's spelling checked against ESPN's players ---------------------------------------

def _scan_edit_key(leg: str) -> str:
    return re.sub(r"\s+", " ", (leg or "").lower()).strip()


def remember_scan_edits(before: list, after: list) -> None:
    """An Edit correction is kept, so the next screenshot with that same line uses the fixed wording."""
    if len(before) != len(after):
        return
    try:
        edits = json.loads(get_setting(0, "scan_edit") or "{}")
    except Exception:
        edits = {}
    if not isinstance(edits, dict):
        edits = {}
    for old, new in zip(before, after):
        old, new = (old or "").strip(), (new or "").strip()
        if old and new and old != new:
            edits[_scan_edit_key(old)] = new[:180]
    if not edits:
        return
    try:
        keep = dict(list(edits.items())[-40:])
        set_setting(0, "scan_edit", json.dumps(keep)[:4000])
    except Exception:
        pass


def free_apply_edits(slip: dict) -> None:
    try:
        edits = json.loads(get_setting(0, "scan_edit") or "{}")
    except Exception:
        return
    if not isinstance(edits, dict) or not edits:
        return
    legs, changed = [], False
    for leg in slip.get("legs") or []:
        hit = edits.get(_scan_edit_key(leg))
        if isinstance(hit, str) and hit.strip():
            legs.append(hit.strip())
            changed = True
        else:
            legs.append(leg)
    if changed:
        slip["legs"] = legs


async def free_fix_names(slip: dict) -> None:
    """'Julian Quifiones' -> 'Julián Quiñones' when ESPN has one clear match (best effort, a few seconds).
    Scanner 4.0 also remembers a match in scan_alias so the next screenshot of the same OCR typo is instant.
    An earlier Edit correction is applied first."""
    free_apply_edits(slip)
    try:
        aliases = json.loads(get_setting(0, "scan_alias") or "{}")
    except Exception:
        aliases = {}
    if not isinstance(aliases, dict):
        aliases = {}
    async def found(name: str) -> list:
        try:
            raw = await asyncio.wait_for(_get_json(ESPN_SEARCH, {"query": name, "limit": 5, "type": "player"}), 6)
            return [it.get("displayName") or "" for it in (raw.get("items") or []) if isinstance(it, dict)]
        except Exception:
            return []
    legs = slip.get("legs") or []
    shapes = [re.match(r"^(.+?) (over|under) ([\d.]+) (.+)$", leg) for leg in legs]
    names, dirty = [], {}
    for m in shapes:
        if not m:
            continue
        raw_name = m.group(1)
        alias = aliases.get(norm_name(raw_name))
        use = alias if isinstance(alias, str) and alias.strip() else raw_name
        dirty[raw_name] = use
        names.append(use)
    names = list(dict.fromkeys(names))
    looked = dict(zip(names, await asyncio.gather(*(found(n) for n in names)))) if names else {}
    fixed, changed = [], False
    name_alts: dict = {}
    for leg, m in zip(legs, shapes):
        if not m:
            fixed.append(leg)
            continue
        raw_name = m.group(1)
        name = dirty.get(raw_name) or raw_name
        items = looked.get(name) or []
        ranked = []
        for it in items:
            if not it:
                continue
            r = difflib.SequenceMatcher(None, norm_name(name), norm_name(it)).ratio()
            ranked.append((r, it))
        ranked.sort(key=lambda pair: pair[0], reverse=True)
        best, score = (ranked[0][1], ranked[0][0]) if ranked else (None, 0.0)
        if best and score >= 0.8 and norm_name(best) != norm_name(raw_name):
            aliases[norm_name(raw_name)] = best
            name, changed = best, True
        elif isinstance(aliases.get(norm_name(raw_name)), str) and aliases[norm_name(raw_name)] != raw_name:
            name = aliases[norm_name(raw_name)]
        others = [it for r, it in ranked if r >= 0.55 and norm_name(it) != norm_name(name)][:4]
        if others:
            name_alts[name] = others
        fixed.append(f"{name} {m.group(2)} {m.group(3)} {m.group(4)}")
    if name_alts:
        slip["_name_alts"] = name_alts
    slip["legs"] = fixed
    if changed:
        try:
            keep = {k: aliases[k] for k in list(aliases)[-80:] if isinstance(aliases.get(k), str)}
            set_setting(0, "scan_alias", json.dumps(keep)[:4000])
        except Exception:
            pass


# ---- Gemini (Google's free tier) ------------------------------------------------------------------

async def read_slip_gemini(attachment) -> Optional[dict]:
    """Same job as read_slip, through Gemini. The key goes in a header, never the URL."""
    import aiohttp
    raw = await attachment.read()
    if len(raw) > MAX_IMAGE_BYTES:
        raise SecImageTooBig(f"{len(raw) // 1024} KB")
    try:
        pngs = await asyncio.to_thread(enlarge_slip, raw)
    except Exception:
        pngs = [raw]
    parts = [{"inline_data": {"mime_type": "image/png", "data": base64.standard_b64encode(b).decode()}} for b in pngs[:5]]
    prompt = SLIP_PROMPT
    if len(pngs) > 1:
        prompt = (f"These {len(pngs)} images are ONE screenshot: the first is the whole thing, the rest are enlarged "
                  "slices of it from top to bottom that overlap a little. Count each leg only once.\n\n" + prompt)
    prompt += f"\n\nToday is {datetime.now(TZ):%A, %B %d, %Y}."
    parts.append({"text": prompt})
    body = {"contents": [{"parts": parts}], "generationConfig": {"temperature": 0, "responseMimeType": "application/json"}}
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent"
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=8)) as session:
        async with session.post(url, json=body, headers={"x-goog-api-key": GEMINI_API_KEY}) as resp:
            if resp.status != 200:
                text = (await resp.text())[:300]
                raise RuntimeError(f"Gemini HTTP {resp.status}: {text}")
            data = await resp.json(content_type=None)
    text = "".join(p.get("text", "") for c in (data.get("candidates") or [])[:1]
                   for p in ((c.get("content") or {}).get("parts") or []))
    slip = extract_json(text)
    if not slip.get("is_slip"):
        return None
    slip["cost"] = as_amount(slip.get("cost"))
    slip["payout"] = as_amount(slip.get("payout"))
    slip["returned"] = as_amount(slip.get("returned"))
    if slip.get("status") not in ("open", "win", "loss", "push"):
        slip["status"] = "open"
    slip["placed"] = slip.get("placed") is not False
    return slip


async def gemini_see(attachment, prompt: str, temperature: float = 0.5, tokens: int = 420,
                     timeout: float = 8) -> str:
    """One short look at a screenshot. No enlarged slices, so it comes back in a few seconds."""
    if not GEMINI_API_KEY:
        return ""
    import aiohttp
    raw = await attachment.read()
    if len(raw) > MAX_IMAGE_BYTES:
        return ""
    mt = sniff_image_type(raw) or "image/jpeg"
    body = {"contents": [{"parts": [
        {"inline_data": {"mime_type": mt, "data": base64.standard_b64encode(raw).decode()}},
        {"text": prompt},
    ]}], "generationConfig": {"temperature": temperature, "maxOutputTokens": tokens}}
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent"
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=timeout)) as session:
        async with session.post(url, json=body, headers={"x-goog-api-key": GEMINI_API_KEY}) as resp:
            if resp.status != 200:
                return ""
            data = await resp.json(content_type=None)
    return "".join(p.get("text", "") for c in (data.get("candidates") or [])[:1]
                   for p in ((c.get("content") or {}).get("parts") or [])).strip()


RESULT_CARD_PROMPT = """This is one bet screenshot. Read the card. Reply with ONLY a JSON object, no other text:
{
  "is_slip": true,
  "platform": "PrizePicks" or the app name,
  "description": short header such as "5-Pick Flex Play",
  "legs": ["Player Name over|under LINE stat"],
  "cost": number risked or null,
  "payout": possible pay if it is still open, or null,
  "returned": amount actually paid if the card is already settled, else null,
  "status": "win" or "loss" or "push" or "open"
}
A PrizePicks result card often says "$3 paid $4.50" (cost 3, returned 4.50) with a Win or Loss chip.
Up arrow means over. Down arrow means under. The line is the number at the right of the row. The number sitting on the colored bar is the result, not the line.
Each player row is one leg. Include a row even when it says DNP.
Use "win" when the chip says Win or the header says paid. Use "loss" when the chip says Loss. Use "open" only when the card has no final result.
Do not invent a player who is not on the screen. "to win" on an entry that is still open is not a win.
"""


async def read_result_card(attachment) -> Optional[dict]:
    """A second look for a settled result card when the first read found no legs."""
    if not GEMINI_API_KEY or attachment is None:
        return None
    text = await gemini_see(attachment, RESULT_CARD_PROMPT, temperature=0, tokens=900, timeout=16)
    if not text:
        return None
    try:
        slip = extract_json(text)
    except Exception:
        return None
    legs = [str(x).strip() for x in (slip.get("legs") or []) if str(x).strip()]
    if len(legs) < 1:
        return None
    slip["is_slip"] = True
    slip["legs"] = legs[:12]
    slip["cost"] = as_amount(slip.get("cost"))
    slip["payout"] = as_amount(slip.get("payout"))
    slip["returned"] = as_amount(slip.get("returned"))
    if slip.get("status") not in ("open", "win", "loss", "push"):
        slip["status"] = "open"
    if slip["status"] == "win" and slip.get("returned") is not None and slip.get("payout") is None:
        slip["payout"] = slip["returned"]
    slip["placed"] = True
    slip["_how"] = "card"
    slip.setdefault("platform", "PrizePicks")
    slip.setdefault("description", "Slip")
    return slip


async def slip_with_card(attachment, slip, reason):
    """Keep a read that already has legs. Otherwise try the result-card look once."""
    if slip and slip.get("legs"):
        return slip, reason
    try:
        rescued = await asyncio.wait_for(read_result_card(attachment), timeout=16)
    except Exception:
        log.warning("Result card read failed", exc_info=True)
        rescued = None
    if rescued and rescued.get("legs"):
        return rescued, None
    return slip, reason


async def read_slip_raced(attachment, budget: float = 18):
    """The short result-card look and the full reader run together.
    An open read waits for the card look, so a Win chip is not thrown out for a stats pass."""
    best_task = asyncio.create_task(read_slip_best(attachment))
    card_task = asyncio.create_task(read_result_card(attachment))
    slip, reason, timed_out, held = None, None, False, None
    pending = {best_task, card_task}
    loop = asyncio.get_running_loop()
    deadline = loop.time() + budget
    try:
        while pending and loop.time() < deadline:
            done, pending = await asyncio.wait(
                pending, timeout=max(0.05, deadline - loop.time()), return_when=asyncio.FIRST_COMPLETED)
            if not done:
                timed_out = True
                break
            ready = []
            for task in done:
                if task.cancelled():
                    continue
                exc = task.exception()
                if exc:
                    log.warning("Slip read failed: %s", type(exc).__name__)
                    continue
                if task is best_task:
                    got, why = task.result()
                    if why:
                        reason = why
                    if got and got.get("legs"):
                        ready.append((got, why))
                    elif got is not None and slip is None:
                        slip = got
                else:
                    got = task.result()
                    if got and got.get("legs"):
                        ready.append((got, None))
            if ready:
                ready.sort(key=lambda item: 0 if item[0].get("status") in ("win", "loss", "push") else 1)
                top, why = ready[0]
                if top.get("status") in ("win", "loss", "push") or not pending:
                    slip, reason = top, why
                    break
                held = (top, why)
    finally:
        for task in (best_task, card_task):
            if not task.done():
                task.cancel()
        await asyncio.gather(best_task, card_task, return_exceptions=True)
    if not (slip and slip.get("legs")) and held:
        slip, reason = held
    if not (slip and slip.get("legs")) and timed_out:
        reason = reason or "that read took too long"
    return slip, reason


# ---- the chain ------------------------------------------------------------------------------------

def _merge_vision(scan: Optional[dict], vision: dict) -> dict:
    """Keep the scan's legs when the picture reader saw fewer, and keep a win or loss either one found."""
    if not isinstance(scan, dict):
        return vision
    out = dict(vision)
    slegs, vlegs = list(scan.get("legs") or []), list(out.get("legs") or [])
    if slegs and len(slegs) > len(vlegs):
        out["legs"] = slegs
    if out.get("cost") is None and scan.get("cost") is not None:
        out["cost"] = scan["cost"]
    if out.get("payout") is None and scan.get("payout") is not None:
        out["payout"] = scan["payout"]
    if out.get("returned") is None and scan.get("returned") is not None:
        out["returned"] = scan["returned"]
    if out.get("status") not in ("win", "loss", "push") and scan.get("status") in ("win", "loss", "push"):
        out["status"] = scan["status"]
    if not out.get("platform") and scan.get("platform"):
        out["platform"] = scan["platform"]
    if not out.get("description") and scan.get("description"):
        out["description"] = scan["description"]
    if out.get("status") in ("win", "loss", "push"):
        out.pop("_unsure", None)
    out.pop("_result_hint", None)
    return out


async def read_slip_best(attachment) -> tuple[Optional[dict], Optional[str]]:
    """Free scan first, then Gemini, then Claude. Returns (slip or None, why it failed or None). A slip the scan
    wasn't sure about comes back with '_unsure' (reasons) when no AI reader could do better: confirm it by hand."""
    reason, unsure_slip = None, None
    for reader in SLIP_READERS:
        if reader == "scan" and TESSERACT:
            try:
                raw = await attachment.read()
                if len(raw) > MAX_IMAGE_BYTES:
                    raise SecImageTooBig(f"{len(raw) // 1024} KB")
                slip = await asyncio.to_thread(free_scan, raw)
            except SecImageTooBig:
                raise
            except Exception as exc:
                log.warning("Free slip scan failed", exc_info=True)
                SLIP_STATE["last_error"] = (now_iso(), f"Free scan: {type(exc).__name__}: {exc}"[:300])
                continue
            if slip is None:
                reason = reason or "it didn't look like a bet slip to me"
                continue
            try:
                await free_fix_names(slip)
                for extra in slip.get("_extra") or []:
                    if isinstance(extra, dict):
                        await free_fix_names(extra)
            except Exception:
                log.debug("Name check skipped", exc_info=True)
            if slip.get("_extra"):
                return slip, None
            if slip.get("_extra"):
                if not slip["_unsure"] and slip["legs"]:
                    free_count("scan")
                    slip.pop("_unsure", None)
                return slip, None
            if slip.get("legs"):
                if not slip.get("_unsure") or slip_result_ready(slip):
                    free_count("scan")
                    if not slip.get("_unsure"):
                        slip.pop("_unsure", None)
                    slip.pop("_result_hint", None)
                    return slip, None
                if slip.get("_result_hint") or any(
                        u in ("the amount risked", "the payout") for u in (slip.get("_unsure") or [])):
                    unsure_slip = slip
                    continue
                slip.pop("_result_hint", None)
                return slip, None
            unsure_slip = slip
            continue
        if reader == "gemini" and GEMINI_API_KEY:
            try:
                slip = await read_slip_gemini(attachment)
            except SecImageTooBig:
                raise
            except Exception as exc:
                log.warning("Gemini slip read failed: %s", str(exc)[:200])
                SLIP_STATE["last_error"] = (now_iso(), f"Reading with Gemini: {type(exc).__name__}: {str(exc)[:200]}")
                continue
            if slip and (slip.get("cost") is not None or slip.get("status") in ("win", "loss", "push")):
                slip = _merge_vision(unsure_slip, slip)
                free_count("gemini")
                slip["_how"] = "gemini"
                return slip, None
            reason = "I couldn't make out the amount risked" if slip else reason
            continue
        if reader == "claude" and ai_enabled() and claude_budget_ok(essential=True) and claude_alive():
            slip, why = await read_slip_claude(attachment)
            if slip is not None and (slip.get("cost") is not None or slip.get("status") in ("win", "loss", "push")):
                slip = _merge_vision(unsure_slip, slip)
                free_count("claude")
                slip["_how"] = "claude"
                return slip, None
            reason = why or reason
    if unsure_slip is not None:
        return unsure_slip, None
    free_count("fail")
    return None, reason


def free_unsure_note(slip: dict) -> str:
    bits = slip.get("_unsure") or []
    return ("🔎 I read this with the free scan but couldn't be sure about " + ", ".join(bits[:3])
            + (" and more" if len(bits) > 3 else "") + ". Check it, then tap 🧾 **Log this slip** (or ✏️ **Edit** to fix it).")


